programs.haiku:
"""Layer-0 MLP down-projection, component 2496: a "perfect tense" detector.

In plain terms, this component reads the past participle that completes a perfect
tense, the verb after has / have / had ("has been", "have taken", "had come",
"has shown"). On that word it predicts about 1; the same verb after was/is (passive),
a modal, "to", or "the" predicts about 0.

Secondary, weaker responses (values are rough typical activations):
- "been" anywhere: about 0.75.
- Milestone words about arrivals, beginnings and celebrations: "arrived", "arrive",
  "coming", "upcoming", "began", "begin", "beginning", "Christmas", "birthday",
  "holiday", "anniversary", plus "officially", "finally", "another", "through": about 0.6.
- "of" right after "end", "beginning" or "start" ("the end of"): about 0.6.
- The chat markers "</think>" and "<tool_response>": about 1.1 to 1.2.
- Everything else: 0.

The program needs only the current token and the one before it (same document).
"""

READS = ()

AUX = {"has", "have", "had", "'ve", "’ve"}
IRREGULAR = {
    "been", "had", "done", "gone", "come", "taken", "given", "seen", "made", "shown",
    "begun", "broken", "chosen", "driven", "eaten", "fallen", "found", "forgotten",
    "got", "gotten", "grown", "held", "kept", "known", "left", "lost", "met", "paid",
    "read", "run", "said", "sent", "set", "shot", "spoken", "spent", "taught", "told",
    "thought", "understood", "won", "written", "became", "become", "brought", "bought",
    "caught", "built", "felt", "fought", "heard", "hit", "put", "sold", "stood",
    "struck", "threw", "withdrawn", "worn",
}
NOT_PARTICIPLES = {"even", "often", "then", "when", "open", "need", "seven", "listen"}
MILESTONE = {
    "arrive", "arrived", "arrives", "arrival", "coming", "comes", "come", "upcoming",
    "incoming", "begin", "began", "begins", "beginning", "officially", "finally",
    "christmas", "birthday", "holiday", "anniversary", "celebrate", "celebration",
    "halloween", "concludes", "another", "through",
}
MARKERS = {"</think>": 1.1, "<tool_response>": 1.2}
ENDS = {"end", "beginning", "start"}


def _word(s):
    return s.strip().lower().strip(".,;:!?'\"()")


def _is_participle(w):
    if w in NOT_PARTICIPLES:
        return False
    return w in IRREGULAR or (len(w) > 3 and (w.endswith("ed") or w.endswith("en")))


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    w = _word(tok)
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(prefix.token_strings[-2]) if same_doc else ""
    if tok in MARKERS:
        return carry, MARKERS[tok]
    if prev in AUX and _is_participle(w):
        return carry, 1.0
    if w == "been":
        return carry, 0.75
    if w in MILESTONE:
        return carry, 0.6
    if w == "of" and prev in ENDS:
        return carry, 0.6
    return carry, 0.0

programs.sol:
"""Lexical signals of becoming, forming, creating, and reaching maturity.

The strongest signal is the Chinese character 成 ('become/accomplish').
Compounds expressing formation retain a strong response; lexicalized words
for success, completion, costs, and membership have weaker responses.
English and a few other languages have smaller related word-family signals.
A weaker 城 spelling signal and conversation-marker offsets are also included.
Most rules inspect the current token. A split Chinese formation word and
a following English article/preposition get phrase-level corrections.
These are spelling and phrase rules, not an inference of sentence meaning.
"""
READS = ()

ENGLISH_FAMILIES = (
    ({'become', 'becoming'}, -0.94),
    ({'became'}, -1.13),
    ({'becomes'}, -0.72),
    ({'create', 'created', 'creating', 'creation'}, -0.93),
    ({'creates'}, -0.69),
    ({'form', 'forms'}, -0.64),
    ({'formed', 'forming', 'formation'}, -1.21),
    ({'composition', 'compositions'}, -1.25),
    ({'compose', 'composed', 'composing', 'composer'}, -0.39),
    ({'constitute', 'constitutes', 'constituted'}, -0.83),
    ({'adult', 'adults', 'adulthood'}, -1.36),
    ({'mature', 'maturity'}, -0.82),
    ({'synthetic'}, -1.04),
    ({'synthesis', 'synthesize', 'synthes'}, -0.65),
    ({'generate', 'generated', 'generating', 'generation'}, -0.34),
    ({'completion', 'creator', 'creative', 'creativity'}, -0.38),
)
FORMATION = {'成为', '成為', '形成', '构成', '構成', '组成', '組成',
             '建成', '养成', '養成', '当成', '當成', '达成', '達成', '造成'}
TRANSFORMATION = {'变成', '變成', '换成', '換成', '生成', '合成', '分成'}
ACHIEVEMENT = {'完成', '成功', '成果', '成就', '成效', '赞成', '贊成',
               '成熟', '成本', '成败', '成敗'}
MEMBERSHIP = {'成员', '成員', '成绩', '成績', '组成部分', '組成部分'}


def chinese_becoming(word):
    if word in {'成', '不成'}:
        return -6.9
    if word in {'而成', '做成', '制成'}:
        return -5.2
    if word == '成了':
        return -5.2
    # Aspect and attributive particles dilute the response in longer tokens.
    root = word.rstrip('了的')
    scale = 0.76 if root != word else 1.0
    for modifier in ('已经', '已經', '已', '将', '將', '就'):
        if root.startswith(modifier):
            root = root[len(modifier):]
            break
    if root in FORMATION or root == '成名':
        return -3.9 * scale
    if root == '做成':
        return -4.8 * scale
    if root in TRANSFORMATION or root == '集成':
        return -2.7 * scale
    if '成年' in root or root == '成人':
        return -3.0 * scale
    if '成为' in root or '成為' in root:
        return -3.9 * min(1.0, 2.5 / len(root))
    if root in MEMBERSHIP or root in {'成员国', '成員國'}:
        return -0.5
    if any(base in root for base in ACHIEVEMENT):
        return -1.2 * scale
    if any(base in root for base in MEMBERSHIP):
        return -0.5
    if root in {'成长', '成長', '成立', '成分', '成都', '成都市'}:
        return -1.8 * scale
    if root.endswith('成'):
        return -3.6 * scale
    return -1.2 * scale


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else 0.0
    raw = token.strip().strip('_./-()[]{}:')
    word = raw.lower()
    value = 0.0
    if '成' in raw:
        value = chinese_becoming(raw)
        if raw == '成' and carry and carry[0] == document and prefix.position:
            before = prefix.text_prefixes[-2][-6:]
            if before.endswith(('構', '构', '組', '组', '形', '合',
                                '变', '變', '转', '轉', '转换', '转化', '翻译')):
                value = -4.3
    elif '城' in raw:
        # 城 (city) is a weaker spelling/phonetic neighbour of 成.
        value = -1.75 / len(raw) ** 1.6
    elif raw in {'성', '성을', '성이'}:
        value = -3.8 if token.startswith(' ') else -2.8
        if len(raw) > 1:
            value = -2.3
    elif raw in {'생성', '구성'}:
        value = -1.4
    elif word == 'into':
        value = -0.60 if token.startswith(' ') else -0.46
        if raw.isupper():
            value *= 0.3
    else:
        for family, strength in ENGLISH_FAMILIES:
            if word in family:
                value = strength
                # 'form' without a word boundary often belongs to an identifier
                # or a larger word, rather than a standalone formation word.
                if word.startswith('form') and not token.startswith(' '):
                    value *= 0.5
                break
        if raw.isupper() and value:
            value *= 0.6
    if not value:
        if raw in {'创建', '創建', '创造', '創造', '创', '造', '做', '做好',
                   '做了', '作', '作为', '作為', '打造', '产生', '產生', '变得', '變得'}:
            value = -0.6
        elif raw in {'入', '加入', '进入', '進入', '投入', 'に入', '融入'}:
            value = -0.45
        elif raw in {'なる', 'なり', 'にな', 'となります', 'となる', 'となり'}:
            value = -1.0
        elif raw in {'になる', 'になって', 'になります', 'になった', 'になり',
                     'くなり', 'っちゃ'}:
            value = -0.5
        elif raw in {'созд', 'создания', 'состав', 'стать', 'создан', 'образ'}:
            value = -0.8
        elif raw in {'menjadi', 'thành', 'tạo'}:
            value = {'menjadi': -1.1, 'thành': -2.7, 'tạo': -0.6}[raw]
    # Mild continuation within 'formation of ...' / 'creating a ...'.
    if -2.0 < previous < -0.4 and word in {'of', 'a'}:
        value += previous * (0.14 if word == 'of' else 0.11)
    if token == '</tool_call>':
        value = -0.30
    elif token == '<|im_start|>':
        value = 0.11
    elif token == '<|im_end|>':
        value = -0.05
    # Carry only a local lexical signal; clear it at document boundaries.
    return (document, value), float(value)

"""Approximate a response to unfinished text units and message boundaries.

Leading UTF-8 fragments receive large values, unlike bytes that complete a
character. For fragments whose bytes are hidden by replacement-character
decoding, the most recently seen script and a leading space estimate strength.
Contraction stems, unfinished escapes, markup/operator prefixes and a few
abbreviation/phrase prefixes receive smaller values. Chat boundaries, carriage
returns and separator runs have separate responses; other tokens predict zero.
State holds only the recent script and resets at document boundaries. This
misses many lexical fragments and token-specific differences in strength.
"""

READS = ()
# Byte-level tokenizers begin with printable bytes, then the remaining bytes.
_PRINTABLE = (*range(33, 127), *range(161, 173), *range(174, 256))
_BYTE_ALPHABET = (*_PRINTABLE, *(b for b in range(256) if b not in _PRINTABLE))
NEGATIVE_STEMS = {
    'don', 'doesn', 'didn', 'isn', 'aren', 'wasn', 'weren', 'hasn',
    'haven', 'hadn', 'wouldn', 'couldn', 'shouldn', 'mustn', 'needn',
}


def script(s):
    for c in reversed(s):
        n = ord(c)
        if 0x4e00 <= n <= 0x9fff:
            return 'han'
        if 0xac00 <= n <= 0xd7af:
            return 'korean'
        if 0x3040 <= n <= 0x30ff:
            return 'japanese'
        if 0x370 <= n <= 0x3ff or 0x1f00 <= n <= 0x1fff:
            return 'greek'
        if 0x400 <= n <= 0x52f:
            return 'cyrillic'
        if 0x600 <= n <= 0x6ff:
            return 'arabic'
        if 0x900 <= n <= 0xdff:
            return 'indic'
        if c.isalpha():
            return 'latin'
    return None


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    if carry is None or carry[0] != doc:
        carry = (doc, 'latin')
    recent_script = carry[1]
    s = prefix.token_strings[-1]
    word = s.strip()
    value = 0.0
    if s == '<|im_end|>':
        value = 2.27
    elif s == '<|im_start|>':
        value = 0.20
    elif '\ufffd' in s:
        token_id = int(prefix.token_ids[-1])
        byte = _BYTE_ALPHABET[token_id] if token_id < 256 else None
        unfinished = prefix.text_prefixes[-1].endswith('\ufffd')
        if byte is not None and 0x80 <= byte < 0xc0:
            # An isolated continuation byte is not a new character's prefix.
            value = 0.5 if unfinished else 0.0
        elif not unfinished:
            value = 0.0
        elif byte is not None:
            if 0xe4 <= byte <= 0xe9:  # The main Han-character range.
                value = 6.4
            elif byte in {0xe0, 0xee, 0xef, 0xf0}:
                value = 1.9
            else:
                value = 3.2
        elif s.startswith(' '):
            value = {'han': 1.4, 'japanese': 1.6, 'korean': 3.9,
                     'greek': 2.4, 'cyrillic': 3.7, 'indic': 0.2,
                     'arabic': 4.0}.get(recent_script, 2.0)
        else:
            # Kana preceding the fragment is useful evidence for a kana suffix;
            # a bare fragment in Japanese may instead be an unfinished kanji.
            value = {'han': 6.3, 'japanese': 6.0, 'korean': 2.0,
                     'greek': 1.7, 'cyrillic': 3.3,
                     'arabic': 4.1, 'indic': 1.4}.get(recent_script, 2.7)
            if script(s) == 'japanese':
                value = 1.9
    elif s == '\r':
        value = 2.0
    elif s.endswith('\\'):
        value = 0.4 if s.startswith(' ') else 0.6
    elif s.startswith('\\x') and len(s) < 4:
        value = 0.7
    elif word == '</':
        value = 0.8
    elif word in {'www', 'std', 'etc', 'according', 'According'}:
        value = 0.8
    elif word in {'Mr', 'Mrs', 'Dr'}:
        value = 0.55
    elif len(word) >= 8 and set(word) == {'='}:
        value = 1.0
    elif len(s) >= 2 and set(s) == {'\xa0'}:
        value = 0.6
    elif word.lower() in NEGATIVE_STEMS:
        value = {'don': 1.0, 'doesn': 1.2}.get(word.lower(), 1.5)
    elif word in {'&', '&&', '&#'}:
        value = 0.75
    elif word in {'â', 'Â'}:
        value = 1.0
    new_script = script(s)
    return (doc, new_script or recent_script), float(value)

programs.luna:
"""Flag byte fragments shown as replacement characters and message endings."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "�" in token:
        return None, 1.9
    if token == "<|im_end|>":
        return None, 2.3
    return None, 0.0

programs.sol:
"""Approximate syntax-marker responses, especially at a document boundary.

The document-opening tokens // plus newline, # plus newline, and <!
produce large positive pulses, matching rare opening-syntax examples in
training. Include/header-guard directives have negative responses. Conversation boundary/tool/thinking markers
have their own small responses. Ordinary text is left at zero: its varied
lexical activations are not captured by this syntax-only approximation.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    if first and token in {'//\n', '#\n'}:
        value = 0.415
    elif first and token == '<!':
        value = 0.517
    elif token == '#include':
        value = -0.113 if first else -0.078
    elif token == '#ifndef':
        value = -0.166 if first else -0.045
    elif first and token == '#':
        value = -0.061
    elif first and token in {'.', ','}:
        value = 0.06
    elif token == '/**\n':
        value = 0.056 if first else 0.033
    elif token == '</think>':
        value = 0.034 if first else 0.10
    elif token == '<tool_call>':
        value = -0.072 if first else 0.047
    elif token == '</tool_call>':
        value = 0.011
    elif token == '<|im_start|>' and first:
        value = -0.022
    elif token == '<|endoftext|>':
        value = -0.142 if first else 0.013
    elif token == '://':
        value = -0.066
    else:
        value = 0.0
    return None, value

"""Approximate a lexical signal for entering, exiting, and returning.

Give large negative values to 'enter' and its inflections, smaller ones
to entry/exit/return vocabulary, the orthographic relatives 'enterprise'
and 'ent', and several multilingual input prompts. Case, word boundaries,
'please/press', re-entry and an '__' prefix adjust the entry signal.
Recognize split inflections and carry a fraction of a strong entry signal
onto the next article or input-related word. Reset this context between
documents. Otherwise predict zero, omitting weak unrelated responses.
"""
import string

READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip().strip(string.punctuation)
    word = token.lower()
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    internal = (raw == token and previous and previous[-1:].isalpha())
    previous_signal = carry[2] if carry is not None and carry[0] == doc else 0.0
    previous_word = previous.strip().strip(string.punctuation).lower()
    value = 0.0
    if word == 'enter':
        value = -5.55
        if token.isupper():
            value = -5.4
        elif token[:1].isupper():
            value = -6.7 if raw == token else -7.0
        if internal:
            value *= 0.45
        if previous_word == 're' or previous.endswith('\\t'):
            value = -5.2 if word == token else -6.7
        if raw.startswith('-'):
            value = -7.8
        if previous.strip() == '__':
            value = -8.6
        if previous_word in ('please', 'press'):
            value -= 1.8
    elif word in ('entered', 'entering', 'enters'):
        value = -4.3 if word == 'entered' else -4.95
    elif word in ('enterprise', 'enterprises'):
        value = -1.55
    elif word in ('entry', 'entries'):
        value = -1.0 if token[:1].isupper() else -1.22
    elif word == 'entrance':
        value = -0.72
    elif word in ('ent', 'entr'):
        value = -1.8 if token[:1].isupper() else -0.8
        if internal:
            value *= 0.25
    elif word in ('exit', 'exits', 'exiting', 'exited'):
        value = -1.22 if word == 'exited' else -1.56
    elif word in ('return', 'returns', 'returned', 'returning'):
        if word == 'return':
            value = -0.90
        elif word == 'returns':
            value = -1.36 if token[:1].isupper() else -1.05
        else:
            value = -0.75
    elif word in ('leave', 'leaving', 'leaves'):
        value = {'leave': -1.05, 'leaving': -1.24, 'leaves': -0.56}[word]
    elif word in ('escape', 'escaping', 'escaped'):
        value = -0.5
    elif token == '请输入':  # Chinese: please enter
        value = -3.7
    elif token.startswith(('进入', '進入')):  # enter
        value = -1.95
    elif token in ('输入', '輸入', '返回'):  # input / return
        value = -1.4
    elif token.startswith(('企业', '企業')):  # enterprise
        value = -1.0
    elif word in ('ingrese', 'ведите', 'digite'):
        # Spanish / Portuguese input prompts, and a Russian prompt fragment
        value = -2.2
    elif word in ('esc', 'typing'):
        value = -0.4 if word == 'esc' else -0.94

    if raw == token and previous_word in ('enter', 'ent'):
        if word in ('ed', 'ing'):
            value = -3.5
        elif word == 'ering':
            value = -5.4
        elif word == 'ers':
            value = -1.6
    if previous_signal < -3.0:
        if word in ('a', 'an', 'the') and raw[:1].isspace():
            value = 0.25 * previous_signal
        elif word in ('into', 'your', 'in', 'to'):
            value = 0.14 * previous_signal
    return (doc, raw, value), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 2501: an "enter / exit / return" word detector.

What it does: its activation is negative and almost entirely set by the current token.
The strongest response (about -4 to -8) is on the verb "enter" in any form: enter,
entered, entering, enters, and in capitals (ENTER, Enter, _ENTER) as in code and UI text.
A medium response (about -1 to -2) is on the words for exit, leave, return and entry, and on
"enter", "input" and "exit" in Chinese and a few other languages (进入, 输入, 退出, 返回).
A weak response is on the fragment "ent" alone. Most other tokens give about 0.

The program reads only the current token. It strips spaces and code punctuation, lower-cases
the word, and looks it up in small concept tables; each table gives a typical activation for
its concept. Anything not listed predicts 0.
"""

READS = ()

PUNCT = " _.-(\t\n\r\"'"

# The verb "enter": the strongest response.
ENTER = {"enter", "entered", "entering", "enters"}
# Enter, input, or enter a place, in other languages.
ENTER_OTHER = {"进入", "進入", "踏入", "输入", "輸入", "入力", "입력", "введите", "digite", "ingrese"}
# Exit, leave, return, and entry: moderate responses.
EXIT = {"exit", "exited", "exiting", "exits", "退出"}
ENTRY = {"entry", "entries", "entrance", "enterprise", "enterprises"}
LEAVE = {"leave", "leaving", "leaves"}
RETURN = {"return", "returns", "returned", "returning", "返回", "返"}
# The fragment "ent" on its own: a weak response.
ENT_FRAGMENT = {"ent"}

TABLE = {}
for words, value in [
    (ENTER, -5.5), (ENTER_OTHER, -2.0), (EXIT, -1.6), (ENTRY, -1.3),
    (LEAVE, -1.1), (RETURN, -0.9), (ENT_FRAGMENT, -0.3),
]:
    for word in words:
        TABLE[word] = value


def step(carry, prefix, upstream):
    """The activation at this position: the table value for the current token's word."""
    word = prefix.token_strings[prefix.position].strip(PUNCT).lower()
    return carry, float(TABLE.get(word, 0.0))

programs.luna:
"""Recognize a few words that make this component contribute negatively.

The harvested examples are dominated by `enter` and code's `return`; `exit`,
`leave`, `entry`, and a few input/output or control words contribute less.
This is a lexical approximation, not a model of the surrounding syntax.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()
    word = ""
    started = False
    for char in token:
        if not char.isalpha():
            if started:
                break
            continue
        started = True
        word += char

    if word.startswith("enter"):
        value = -5.7
    elif word.startswith("return"):
        value = -0.9
    elif word.startswith("exit"):
        value = -1.6
    elif word.startswith("leave"):
        value = -1.05
    elif word.startswith("entry"):
        value = -1.35
    elif word.startswith("echo"):
        value = -0.65
    elif word.startswith("ingrese"):
        value = -2.1
    elif word.startswith("raise"):
        value = -0.45
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""A literal-tab trigger with separate rules for document-opening typography.

Single tabs are strongly positive, especially after newline and less so after
another tab. Double tabs and tab-plus-space indentation are weaker. Document
openings are scored by whitespace, case, word class, code headers, and incomplete
character tokens. Space-prefixed capitalized function words are especially
negative. These opening effects fade toward a near-zero background prediction.

This is a coarse approximation: it omits individual-token residual variation.
State resets whenever the document label changes.
"""
READS = ()

INDEFINITE_ARTICLES = frozenset({"a", "an"})
PREPOSITIONS = frozenset({"in", "on", "to", "for", "as", "at", "by", "from"})
MULTILETTER_PRONOUNS = frozenset({"you", "we", "he", "she", "it", "they"})
MODULE_HEADERS = frozenset({"import", "package", "#include"})
OTHER_FUNCTION_OPENERS = frozenset({"now", "once", "here", "there", "if", "all", "no"})


def opening_value(token):
    word = token.strip()
    if not word:
        if token == "\n":
            return 0.315
        if token == "\n\n":
            return 0.14
        if token in {" ", "  "}:
            return 0.24
        return 0.0
    if token in MODULE_HEADERS:
        return 0.35
    if token.startswith(("//", "/*", "#!/")):
        return 0.34
    if token == "The":
        return 0.4
    if token.startswith(".") and len(token) > 1 and token[1].isalpha():
        return -0.15
    if token.startswith("<|"):
        return -0.14
    if word.startswith("\ufffd"):
        return -0.5
    if token.startswith(" "):
        if word[0].isupper():
            lower = word.lower()
            if word == "The":
                return -4.48
            if word == "This":
