    w = s.strip()
    if s == "\t":
        return "tab"
    if not w:
        return "space"
    if w[0].isdigit():
        return "digit"
    if not w[0].isalnum():
        return "punct"
    spaced = s[:1] == " "
    return ("spaced" if spaced else "joined") + ("_Cap" if w[0].isupper() else "_word")

FIRST_TOKEN = {
    "tab": 0.63, "space": 0.16, "digit": 0.08, "joined_Cap": 0.03, "joined_word": -0.02,
    "punct": -0.03, "spaced_Cap": -0.95, "spaced_word": -0.18,
}

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    first = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if first:
        return carry, float(FIRST_TOKEN.get(_kind(s), -0.1))
    return carry, 0.69 if s == "\t" else 0.0

