    (('remarkable', 'remarkably'), -0.5),
    (('remember', 'remaining'), -0.4),
    (('remova', 'remover'), -1.05),
    (('remov',), -0.45),
    (('remind', 'remodel', 'remake', 'remark', 'remar'), -1.6),
