    value = 0.0

    if word in {'rem', 'ren'}:
        if word == 'rem':
            value = -6.3 if title else -4.9
            if not spaced:
                value += 1.3
        else:
            value = -3.3 if title else -2.5
            if not spaced:
                value += 0.4 if title else 0.7
            if raw.startswith('-'):
                value = -3.3
    elif word == 're':
        if title:
            value = -0.2
        elif raw.startswith(('.', '_')):
            value = -0.9
        elif token.isupper():
