        value = -0.04 if raw == 'res' else -0.3
    elif word in {'retr', 'reh', 'rell', 'reck'}:
        value = -0.9
    elif word.startswith('review'):
        value = -1.3 if word.endswith('s') else -1.0
    elif word in {'renal', 'kidney', 'kidneys', '肾', '肾脏'}:
        value = -2.2 if word == 'renal' and spaced else -1.6
    elif word.startswith('рем'):  # Cyrillic rem
        value = -2.5 if spaced and word == 'рем' else -1.6
    elif word in {'提醒', '评审', '重新'}:  # remind, review, anew
        value = -2.1 if word == '提醒' else -1.0
