from math import sqrt

READS = ()
BE = {'is': 1., 'are': 1.04, 'am': .83, 'was': 1.15, 'were': 1.12,
      'be': .8, 'been': .95, 'being': .8, "'s": .5, "'re": .85, "'m": .85}
NEGATIVE_BE = {'isn': 1., 'aren': 1., 'wasn': 1.15, 'weren': 1.1, 'ain': .55}
