OBJECTS = set('it this you me us them him her'.split())
MODALS = set('can could may might must need'.split())
AUXILIARIES = set('do does did have has had will would shall should'.split())
CAUSATIVE = set('make makes made making'.split())

# Typical activation magnitudes after 'is'; these are word classes, not IDs.
MODIFIER_CLASSES = (
    (3.4, 'always never often already'),                 # frequency
    (3.05, 'usually typically generally commonly constantly regularly'),
    (2.65, 'not also still now currently actually truly indeed clearly'),
    (2.4, 'probably possibly certainly definitely likely simply merely'),
    (2.6, 'recently originally previously initially finally ultimately '
           'officially preferably reportedly frequently occasionally'),
    (2.1, 'then later again sometimes seldom ever thus therefore '
           'thereby hereby instead mainly mostly largely particularly '
           'nevertheless nonetheless otherwise afterwards hence '
           'somehow nowadays once'),
    (1.9, 'only just solely completely entirely fully either yet'),
    (1.3, 'all both neither each there here first further somewhat'),
    (.75, 'even genetically sexually politically statistically internally'),
)
MAGNITUDES = {w: a for a, words in MODIFIER_CLASSES for w in words.split()}
MAGNITUDES.update({
    'not': 2.7, 'very': .95, 'well': 1.15, 'much': 1., 'more': 1.2, 'less': .6,
    'most': 1.65, 'so': 1.5, 'too': 1.65, 'quite': 1.8, 'rather': 1.6,
    'almost': 1.5, 'nearly': 1.1, 'pretty': 1.1, 'no': 1.1,
    'really': 2., 'soon': 2.8, 'perhaps': 1.55, 'maybe': .9,
    'plainly': 2.8, 'surely': 3., 'evidently': 3., 'best': 1.1,
    'easily': 2.6, 'extremely': .75, 'approximately': 1., 'exactly': 1.25,
    'negatively': .6, 'itself': .6, 'himself': 1.8, 'herself': 1.8, 'themselves': 2.,
})
LY_NONADVERBS = set('family friendly lovely lonely lively ugly elderly costly '
                   'silly chilly holy july italy worldly deadly early timely '
                   'daily'.split())


def word(raw):
    return raw.strip().lower().replace('’', "'").lstrip('—–')


def magnitude(w):
    if w in PERSONAL or w == 'I':
        return 2.
    if w == 'this':
        return 1.3
    if w in MAGNITUDES:
        return MAGNITUDES[w]
    if (w.isalpha() and w.endswith('ly') and len(w) > 3
            and w not in LY_NONADVERBS):
        return 1.75
    return 0.


def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        prev_raw, cue, position = '', 0., 0
    else:
        _, prev_raw, cue, position = carry
        position += 1
    w, prev = word(raw), word(prev_raw)
    boundary = raw[:1].isspace() or prev_raw[-1:].isspace()
    if raw.strip() == 'I' and boundary:
        w = 'I'
    a, value = magnitude(w), 0.
    if w == 'least' and prev == 'at':
        value = -.7 - 1.3 * cue
    elif cue and a and boundary:
        if ((prev == 'are' and w == 'you')
                or (prev == 'am' and w == 'I')):
            a = 2.6 / cue
        scale = .925 + .48 / sqrt(position + 1)
        if raw.strip().istitle() and w != 'I':
            scale *= .55
        if raw.strip() == 'IT':
            scale *= .4
        value = -cue * a * scale
    elif w in {"'t", "n't"}:
        value = -2.35 * NEGATIVE_BE[prev] if prev in NEGATIVE_BE else -.15
    elif w == 'not':
        value = (1.1 if prev in MODALS else
                 .15 if prev in AUXILIARIES else -.3)
        if prev == 'or':
            value = .45
        if position == 0 or raw.strip().istitle():
            value = -1.1 if position == 0 else -.7
    elif w == 'longer' and prev == 'no':
        value = -1.
    elif w in OBJECTS and prev in CAUSATIVE:
        value = -1.7 if w == 'it' else -1.
    elif w in OBJECTS and prev in {'get', 'got', 'keep', 'kept', 'find', 'call'}:
        value = -.8 if w == 'it' else -.4
    elif prev == 'not':
        value = -.45 * a
    elif prev in {"'t", "n't"}:
        value = -.1 * a
    elif a >= 2.5:
        value = -.1

    whole = (boundary or not prev_raw or not prev_raw[-1:].isalpha()
             or raw.startswith(('—', '–')))
    if w in BE and (whole or w.startswith("'")):
        cue = BE[w]
    elif w in NEGATIVE_BE and whole:
        cue = NEGATIVE_BE[w]
    elif w == 'n' and prev in BE:
        raw = prev_raw + raw
    elif w in {'not', "'t", "n't"}:
        cue *= .6
    elif w in {'a', 'an', 'the'}:
        cue *= .35
    elif w in {'more', 'less', 'only'}:
        cue *= .15
    elif a or w == 'at':
        cue *= .55
    else:
        cue = 0.
    return (doc, raw, cue, position), float(value)

