    w: strength
    for strength, words in (
        (4.7, 'paper'),
        (3.7, 'study article'),
        (2.9, 'invention work section chapter thesis research manuscript essay'),
        (2.2, 'page report review book guide document note disclosure publication handbook'),
        (1.7, 'file post blog project lesson letter tutorial subsection notebook'),
        (1.0, 'question course website journal application worksheet talk notice'),
        (0.7, 'text content script example topic message site part video'),
    )
    for w in words.split()
