programs.luna:
"""A discourse cue for named textual objects versus generic demonstrative phrases."""

READS = ()

# Academic and legal objects that writers refer to within a text.
FORMAL_REFERENTS = {
    "paper", "article", "study", "work", "invention", "section",
    "subsection", "review", "report", "research", "disclosure",
}

# Other named things a text can point back to.
TEXT_OBJECTS = {
    "manuscript", "thesis", "experiment", "course", "page", "letter",
    "chapter", "appendix", "file", "post", "book", "lesson", "blog",
    "project", "context", "question", "part", "website", "talk",
    "notice", "poem", "literature", "notebook", "embodiment",
    "document", "guide", "publication", "text", "application",
    "note", "investigation", "contribution", "discussion", "recipe",
    "figure", "table", "equation", "formula", "paragraph", "example",
    "本文", "文章", "記事", "연구", "논문", "블로그", "课程",
    "artículo", "página", "trabalho", "стать",
}

# Common predicate-like continuations after "this" or "that".
CLAUSE_STARTS = {
    "is", "was", "are", "were", "be", "been", "being", "can",
    "could", "will", "would", "has", "have", "had", "means",
    "shows", "suggests", "includes", "requires", "makes", "does",
    "involves", "holds", "avoids", "equal", "with",
    "may", "might", "often", "isn", "should",
}

# Generic time/situation phrases, unlike a named text object.
GENERIC_REFERENTS = {
    "case", "time", "year", "week", "day", "date", "way", "same",
    "one", "many", "last", "type", "past", "next", "world",
    "month", "season", "era",
}


def step(carry, prefix, upstream):
    """Use the current word and short preceding text to recognize reference phrases."""
    doc = prefix.document_ids[-1]
    before = "" if carry is None or carry[0] != doc else carry[1]
    current = prefix.token_strings[-1]
    word = current.strip().lower()
    context = before.lower()
    value = 0.0

    referential = context.endswith(("this ", "of this ", "present "))
    formal = word in FORMAL_REFERENTS
    if word in FORMAL_REFERENTS or word in TEXT_OBJECTS:
        if referential:
            value = 2.8 if formal else 2.2
        elif context.endswith(("following ", "proposed ", "described ")):
            value = 1.0
    elif word == "invention" and context.endswith("the "):
        value = 2.6
    elif word == "present" and context.endswith(("the ", "of the ")):
        value = 1.1
    elif word == "following" and context.endswith("the "):
        value = 0.9
    elif word in CLAUSE_STARTS and context.endswith(("this ", "that ")):
        value = -1.3
    elif word in GENERIC_REFERENTS and context.endswith(("this ", "of this ")):
        value = -0.9

    if current == "->" and context.endswith("this"):
        value = 1.0
    if word == "herein":
        value = 1.2

    return (doc, (before + current)[-100:]), float(value)

programs.sol:
"""A surface-level detector of coordination, especially English 'and'/'or'.

Conjunctions after ordinary words are positive. Numbers and punctuation,
particularly closing brackets, weaken that response. Short whole words,
pronouns, particles, determiners and number words strengthen it; fragments,
capitalized words and abstract-noun endings weaken it. Other European
conjunctions, ampersands and slash/dash separators have smaller responses.
A 32-token function-word count disambiguates Romance conjunctions from
variables and the Latin citation marker "et" in English prose. Contrast and
sequencing words, and Chinese "和", receive small negative predictions.
Everything else is zero; the state resets at each document boundary.
"""
READS = ()

# These function words distinguish prose conjunctions from variables and citations.
ROMANCE = set(
    'de la le les des du un une que pour dans en au aux avec à est ce pas '
    'del el los las por para una con es se su pero como lo al '
    'di il gli delle della degli dei che per nella non nel sono '
    'da do dos das um uma em com não é os no na seu sua'.split())
ENGLISH = set(
    'the a an of to in is are was were be by for with that this these those '
    'it its and or on from not as at have has had will would can could '
    'you your they their we our he she his her'.split())

PRONOUNS = set('i me you he him she her it we us they them myself yourself '
               'himself herself itself ourselves themselves'.split())
PARTICLES = set('back up out off over down away on in around through '
                'together now again there here'.split())
NUMBER_WORDS = set('one two three four five six seven eight nine ten '
                   'first second third fourth hundred thousand'.split())
DETERMINERS = set('this that these those each every any all both such which '
                  'some other either neither more most much many few less'.split())
ADJECTIVES = set('good bad great poor long short safe right wrong large small '
                 'big little old new strong weak high low early late'.split())
ABSTRACT_ENDINGS = ('tion', 'sion', 'ment', 'ness', 'ity', 'ance', 'ence')
CONJUNCTIONS = {
    'und': 0.52, 'et': 0.40, 'ou': 0.53, 'oder': 0.32,
    'e': 0.32, 'y': 0.18, 'o': 0.08, 'och': 0.29,
    'og': 0.23, 'ja': 0.18, 'и': 0.07, 'или': 0.15,
    'nor': 0.24,
}


def english_joiner(previous, alternative):
    """A stronger conjunction after ordinary words, not notation."""
    s = previous.strip()
    if not previous:
        return 0.81 if not alternative else 0.49
    if s.isalpha():
        value = 0.80 - 0.026 * (min(len(s), 14) - 5)
        if alternative:
            value = 0.56 - 0.022 * (min(len(s), 14) - 5)
        if len(s) == 1:
            value -= 0.32 if alternative else 0.46
        if not previous.startswith(' '):
            value -= 0.18 if alternative else 0.22
        if s.isupper() and len(s) > 1:
            value -= 0.23 if alternative else 0.35
        elif s.istitle():
            value -= 0.05 if alternative else 0.07
        lower = s.lower()
        if previous.startswith(' '):
            if lower in PRONOUNS:
                value += 0.32
            if lower in PARTICLES:
                value += 0.13 if alternative else 0.32
            if lower in NUMBER_WORDS:
                value += 0.46 if alternative else 0.14
            if lower in DETERMINERS:
                value += 0.19 if alternative else 0.26
            if lower in ADJECTIVES:
                value += 0.08 if alternative else 0.21
        if len(s) > 5 and lower.endswith(ABSTRACT_ENDINGS):
            value -= 0.08 if alternative else 0.16
        return value
    if any(c.isdigit() for c in s):
        return 0.13 if alternative else 0.20
    if s == ',':
        return 0.42 if alternative else 0.49
    if s and s[0] in ')]}':
        return -0.06 if alternative else -0.02
    if s in ('"', "'", '”', '“', '`'):
        return 0.19 if alternative else 0.38
    if s in (';', '.', ':'):
        return 0.13 if alternative else 0.32
    if s in ('-', '–', '—'):
        return 0.30 if alternative else 0.60
    if not s:
        return 0.10 if alternative else 0.20
    return 0.18 if alternative else 0.29


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent, romance, english = '', (), 0, 0
    else:
        _, previous, recent, romance, english = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0
    if word in ('and', 'or', '-and'):
        value = english_joiner(previous, word == 'or')
        if word == '-and':
            value += 0.5
        elif not token.startswith(' '):
            value *= 0.4
    elif word == '&':
        s = previous.strip()
        value = 0.78 if s.isalpha() and len(s) > 1 else 0.26
        if any(c.isdigit() for c in s):
            value = 0.40
        if token == '&':
            value *= 0.5
    elif word in ('And', 'Or', 'AND', 'OR'):
        value = {'And': 0.45, 'Or': 0.26, 'AND': 0.13, 'OR': 0.18}[word]
    elif word in ('et', 'e', 'y', 'o'):
        if romance >= 2 and romance > english:
            value = {'et': 0.58, 'e': 0.57, 'y': 0.47, 'o': 0.15}[word]
        elif english > romance:
            value = {'et': 0.15, 'e': 0.06, 'y': 0.0, 'o': 0.0}[word]
        else:
            value = {'et': 0.26, 'e': 0.14, 'y': 0.02, 'o': 0.0}[word]
        if not token.startswith(' '):
            value *= 0.5
    elif word.lower() in CONJUNCTIONS:
        value = CONJUNCTIONS[word.lower()]
        if not token.startswith(' '):
            value *= 0.6
    elif word == '/':
        s = previous.strip()
        if s.isalpha():
            if token.startswith(' '):
                value = 0.38
            else:
                value = 0.41 if previous.startswith(' ') else 0.23
        elif any(c.isdigit() for c in s):
            value = 0.19 if token.startswith(' ') else 0.14
        elif previous.startswith(('/', '_', '.')):
            value = 0.03
        else:
            value = 0.24 if token.startswith(' ') else 0.18
    elif token == ' -':
        s = previous.strip()
        if s.isalpha() and len(s) > 1:
            value = 0.22
        elif any(c.isdigit() for c in s):
            value = 0.13
        else:
            value = 0.03
    elif word == '和':
        value = -0.29 if token.startswith(' ') else -0.15
    elif word == 'but':
        value = -0.086
    elif word in ('so', 'then', 'even', 'either', 'whereas'):
        value = -0.085
    flags = (int(word.lower() in ROMANCE), int(word.lower() in ENGLISH))
    if len(recent) == 32:
        romance -= recent[0][0]
        english -= recent[0][1]
        recent = recent[1:]
    recent += (flags,)
    return (doc, token, recent, romance + flags[0], english + flags[1]), float(value)

programs.haiku:
"""Coordinating conjunctions: the component fires on "and", "or" and their translations
("und", "et", "ou", "y", "&") and on a slash used as a separator. It is strongest when the
conjunction joins ordinary words in prose, weaker after a comma or a number, and silent
after a closing bracket."""

READS = ()

# How strongly each conjunction token fires on its own (activation units).
STRENGTH = {}
for w in [" and", "and", " And", "And", "-and"]:
    STRENGTH[w] = 0.6
for w in [" or", "or", " Or", " nor"]:
    STRENGTH[w] = 0.45
for w in [" und", " Und", " et", " Et", " ou", " oder", " och", " og", " &", "&"]:
    STRENGTH[w] = 0.5
for w in [" y", " e"]:
    STRENGTH[w] = 0.25
for w in [" /", "/"]:
    STRENGTH[w] = 0.3

CLOSERS = (")", "),", "]", "$")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    base = STRENGTH.get(tok, 0.0)
    if base == 0.0 or len(prefix.token_strings) < 2:
        return None, base
    before = prefix.token_strings[-2]
    if before.strip().isdigit():
        return None, base * 0.33
    if before in CLOSERS:
        return None, 0.0
    if before.strip().isalpha() and before.strip().islower():
        return None, base * 1.2
    if before == ",":
        return None, base * 0.8
    return None, base * 0.8

programs.luna:
"""Use English coordination words and two visible list separators as cues."""
READS = ()

SIGNALS = {
    "and": 0.69,
    "or": 0.53,
    "/": 0.32,
    "-": 0.18,
}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    return None, float(SIGNALS.get(word, 0.0))

programs.sol:
"""A person/name-boundary response, estimated from readable lexical cues.

Track the previous Latin word across subword pieces. Personal pronouns, human
roles, familiar names, and capitalized words split into several pieces strengthen
responses to possessives and finite verbs. Name continuations are weakly negative.
A few East Asian subject particles, honorifics and reporting verbs have fixed responses.
The three subject amplitudes below are calibrated strengths, not probabilities.
State, including names learned within the row, resets at document boundaries.
"""
import re

READS = ()
NAMES = set('''
