def subject(word, person, chunks, capitals, punct):
    """Return verb strength, possessive activation, and name-link strength."""
    w = word.lower()
    if punct:
        return .104, .400, -.035
    if w in {'it', 'this', 'that', 'there', 'here', 'what', 'something', 'nothing', 'let'}:
        return -.125, -.099, .065
    if w in {'they', 'we', 'you'}:
        return .016, 0., -.077
    if w == 'i':
        return .149, .792, .069
    if w in {'he', 'she', 'him', 'her', 'himself', 'herself'}:
        return 1., 1.263, .209
    if w == 'who':
        return .589, .825, .284
    if person and word[:1].isupper():
        return 1.908, 2.914, 1.
    if w in FUNCTION:
        return -.048, .546, -.024
    if w in HUMANS:
        return .516, 1.025, .147
    if w in INSTITUTIONS:
        return .106, .614, -.004
    if word.isupper() and len(word) > 1:
        return .390, 1.429, .110
    if word[:1].isupper():
        if w in NAMES:
            return 1.908, 2.914, 1.
        if w.endswith(SURNAMES) and len(w) > 4:
            return 1.134, 2.641, .816
        if chunks > 1:
            return 1.181, 2.519, .505
        return (.775, 1.729, .218) if capitals > 1 else (.433, 1.625, .111)
