def response(token, amplitudes, opened, proper, person):
    verb, possessive, link = amplitudes
    w = token.strip().lower()
    if w in {"'s", '’s'}:
        return possessive
    if w in {'は', 'が'}:
        return .357
    if w in {'은', '는', '가'}:
        return .395
    if w == '이':
        return .202
    if w in {'氏', '先生', '老师', 'さん'}:
        return .562
    if w in {'表示', '指出', '认为', '介绍', '提出', '宣布'}:
        return .688
    if w in {'在', '被', '还', '曾', '已经'}:
        return .256
    if w in {'(', ':', "'", '’'}:
        base, gain = {'(': (.017, .890), ':': (-.002, .263),
                      "'": (.005, .621), '’': (.005, .621)}[w]
