        return .011 + .535 * verb
    if w in {'do', 'does', 'did', 'doesn', 'didn'}:
        return .040 + .693 * verb
    if w in {'said', 'says'}:
        return -.051 + .616 * verb
    if w in {'explains', 'explained', 'describes', 'described',
             'introduces', 'introduced'}:
        return .257 + 1.289 * verb
    if w in {'wrote', 'began', 'continued', 'worked', 'grew'}:
        return .458 + 1.062 * verb
    if w in {'himself', 'herself'}:
        return .364
    if w in VERBS:
        return .071 + .736 * verb
    if w in IRREGULAR or (len(w) > 3 and w.isalpha() and w.endswith('ed')):
        return .029 + .739 * verb
    if len(w) > 3 and w.isalpha() and w.endswith('s') and w not in FUNCTION:
        return .001 + .205 * verb
    if w.endswith('ly') or w in {'also', 'just', 'now', 'then', 'never', 'already',
                                'eventually', 'further', 'still', 'always',
                                'later', 'again', 'often', 'once'}:
        return .012 + .518 * verb
    if w in {'and', '&', 'et'}:
        return .005 + .677 * link
    if w in {'of', 'in', 'at', 'to', 'for', 'from', 'on', 'as', 'with', 'who'}:
        return .007 + .395 * link
    if w in {'v', 'vs', 'versus'}:
        return .052 + .815 * link
    return .002


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, 0, False, False, False, frozenset())
    _, word, chunks, capitals, person, opened, punct, names = carry
    token = prefix.token_strings[-1]
    person = person or word.lower() in names or word.lower() in NAMES
    proper = bool(word[:1].isupper() and word.lower() not in FUNCTION and not punct)
    value = response(token, subject(word, person, chunks, capitals, punct),
                     opened, proper, person)
    if person and proper and not token[:1].isalpha():
        names = names | {word.lower()}
    matches = list(WORDS.finditer(token))
    for i, match in enumerate(matches):
        part = match.group()
        if part[0].isalpha():
            if i == 0 and match.start() == 0 and opened:
                word += part
                chunks += 1
            else:
                if person and proper:
                    names = names | {word.lower()}
                upper = part[:1].isupper()
                person = upper and (word.lower() in TITLES or word.lower() in HUMANS
                                    or (proper and person))
                capitals = capitals + 1 if upper and proper else int(upper)
                word, chunks = part, 1
            punct, opened = False, True
        else:
            punct = not (part == '.' and word.lower() in TITLES)
            opened = False
    if not token or not token[-1].isalpha():
        opened = False
    if not matches and token.strip():
        word, chunks, capitals, person, punct, opened = '', 0, 0, False, False, False
    return (doc, word, chunks, capitals, person, opened, punct, names), float(value)

