    pieces = []
    j = len(strs) - 2
    while j >= 0 and len(pieces) < 6:
        piece = strs[j].lstrip(" ")
        if not piece.isalpha():
            break
        pieces.append(piece)
        if strs[j].startswith(" "):
            break
        j -= 1
    return "".join(reversed(pieces))


def is_person(word):
    """A person pronoun or person noun, or a capitalised name (not a sentence-opening word)."""
    if word.lower() in PERSON_WORDS:
        return True
    return word[:1].isupper() and word not in NOT_NAMES


def is_past_verb(token):
    """A lowercase past-tense verb: -ed form, a common irregular past, or a modal."""
    w = token[1:] if token[:1] == " " else ""
    return w.islower() and (w.endswith("ed") or w in IRREGULAR)


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    strs = prefix.token_strings
    cur = strs[-1]
    word = previous_word(strs)
    if cur in ("'s", "’s"):
        if word.lower() in NOT_SUBJECTS:
            return None, 0.0
        if is_person(word):
            return None, PREDICATE[cur]
        return None, OTHER_POSSESSIVE if word.isalpha() else 0.0
    if not is_person(word):
        return None, 0.0
    if cur in PREDICATE:
        return None, PREDICATE[cur]
    if cur[1:] in MODALS and cur[:1] == " ":
        return None, MODAL
    if is_past_verb(cur):
        return None, VERB
    return None, 0.0

programs.luna:
"""Estimate a small grammar cue from possessives and short function words.

Predict a strong response for English 's unless it follows a subject pronoun,
where it often means "is" or "has"; assign smaller signed responses to some
auxiliaries, reporting verbs, grammar markers, and opening parentheses.
"""

READS = ()

POSSESSIVE_S = {"'s", "’s"}
SUBJECT_PRONOUNS = {"he", "she", "it", "they", "we", "i", "you"}
AUXILIARIES = {
    "am": 0.01,
    "is": 0.13,
    "are": -0.04,
    "was": 0.50,
    "were": 0.02,
    "be": 0.0,
    "been": 0.05,
    "being": -0.08,
    "have": -0.02,
    "has": 0.40,
    "had": 0.55,
    "do": 0.05,
    "does": 0.10,
    "did": 0.15,
}
CLAUSE_MARKERS = {"said": 0.45, "stated": 0.45, "argued": 0.40}
GRAMMATICAL_MARKERS = {
    "は": 0.35,
    "が": 0.28,
    "은": 0.25,
    "는": 0.22,
    "被": 0.30,
    "在": 0.20,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if token in POSSESSIVE_S:
        if len(prefix.token_strings) > 1 and (
            prefix.document_ids[-2] == prefix.document_ids[-1]
        ):
            previous = prefix.token_strings[-2].strip().lower()
            if previous in SUBJECT_PRONOUNS:
                return None, 0.20
        return None, 1.05
    if token in AUXILIARIES:
        value = AUXILIARIES[token]
        if len(prefix.token_strings) > 1 and (
            prefix.document_ids[-2] == prefix.document_ids[-1]
        ):
            previous = prefix.token_strings[-2].strip()
            if (
                previous
                and previous[0].isupper()
                and previous.lower() not in SUBJECT_PRONOUNS
                and token == "has"
            ):
                value += 0.45
            elif (
                previous
                and previous[0].isupper()
                and previous.lower() not in SUBJECT_PRONOUNS
                and token == "was"
            ):
                value += 0.25
        return None, value
    if token in CLAUSE_MARKERS:
        return None, CLAUSE_MARKERS[token]
    if token in GRAMMATICAL_MARKERS:
        return None, GRAMMATICAL_MARKERS[token]
    if token in {"(", "（", "["}:
        return None, 0.07
    return None, 0.0

