    if word == 'as' and previous == 'known':
        value = -1.4
    elif word == 'as' and previous == 'to' and 'referred' in recent:
        value = -1.2
    elif word == 'of' and previous in {'call', 'calling'}:
        value = -2.3 if previous == 'call' else -1.5
    elif word == 'to' and previous in {'call', 'calls'}:
        value = -0.8
    elif word == 'number' and previous in {'phone', 'telephone', 'mobile'}:
        value = -0.8
    elif word == '调':
