programs.haiku:
"""Calling and naming words, for layer 0 MLP component 2514.

A lexical detector for the word that introduces a call, an invocation, or a name.
It goes strongly negative on:
  - "call" and its forms (phone call, function call, "Call" in code), the strongest (about -5.5);
  - "called" (about -3), and "invoke" / "invocation" (about -1.5);
  - "named", "termed", "dubbed" (about -1.3);
  - "name", "names", "rename" and "contact", "phone", "telephone" (about -0.8 to -1.3);
  - the same ideas in other languages: 叫, 呼, 喊, 召唤, 拨打, gọi (about -3 to -5);
  - "用" after "调" (调用, invoke a function, about -4.5);
  - "as" after "known" or "to" ("known as", "referred to as", about -1.2).
Everywhere else it predicts 0. Each token is lowercased with spaces and punctuation stripped
before lookup, so " Call", ".call" and "call" all match.
"""

READS = ()

CALL = {"call", "calls", "calling", "callee", "caller", "callable", "叫", "呼", "喊", "召唤", "拨打", "gọi"}
CALLED = {"called", "-called"}
NAMED = {"named", "termed", "dubbed"}
INVOKE = {"invoke", "invoked", "invocation", "invokes"}
NAME = {"name", "names", "rename", "renamed", "nickname", "名", "名称", "名字", "稱"}
CONTACT = {"contact", "contacts", "phone", "telephone", "tel", "电话", "電話", "通讯", "問い合わせ"}
LABEL_PRECEDERS = {"known", "to"}

VALUE = {}
for w in CALL: VALUE[w] = -5.5
for w in CALLED: VALUE[w] = -3.0
for w in NAMED: VALUE[w] = -1.3
for w in INVOKE: VALUE[w] = -1.5
for w in NAME: VALUE[w] = -0.8
for w in CONTACT: VALUE[w] = -1.3


def _word(token):
    return token.strip().strip("._-\"'(){}[]:,;").lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    prev = _word(prefix.token_strings[-2]) if len(prefix.token_strings) > 1 else ""
    value = VALUE.get(word, 0.0)
    if word == "as" and prev in LABEL_PRECEDERS:
        value = -1.2
    if word == "用" and prev == "调":
        value = -4.5
    return None, float(value)

