        match = re.search(r'([A-Za-z]+)\s*$', recent)
        previous = match.group(1).lower() if match else ''
    value = SCOPE_WORDS.get(lower, PAIR_TRANSLATIONS.get(word, 0.0))
    if lower == 'both':
        value = -7.9
        if previous in PREPOSITIONS:
            value = -8.2
        elif previous in CONNECTIVES or previous in {'are', 'were'}:
            value = -6.8
        elif previous in ARITHMETIC:
