        scores['Polish'] += 3
    if sum(lower.count(c) for c in 'řěů') >= 2:
        scores['Czech'] += 3
    best = max(scores, key=scores.get)
    if scores[best] < 2:
        return 'Other'
    if scores[best] <= scores['English']:
        return 'English'
    return best


def step(carry, prefix, upstream):
