                 '+': 2.45, '/': 3.80, '{': 3.40}.get(stem[0], 3.08)
    elif stem in ('ii', 'iii'):
        if token != stem or not continuing:
            value = 1.35 if stem == 'ii' else 0.90
        else:
            value = 0.20
    elif stem.startswith(('(', '[')) and stem[1:] in ('ii', 'iii'):
        value = 1.65 if stem[1:] == 'ii' else 0.90
    elif stem == 'j':
