"""A local detector for the beginning of a condition or tested expression.

Strongest at `if (` and `if not`, weaker for loops, assertions and logical
operators. Parentheses fused to words are weaker; spelling and indentation
also adjust the response. State stores the previous token and how recently
a condition keyword appeared, resetting between documents. Small rules cover
test functions, loop exits, document-start markers and quoted JSON `name`.
Constants approximate training responses; identifier-specific variations
and unrelated lexical responses are deliberately left out.
"""
READS = ()
CONDITIONS = {'if', 'elif', 'elseif', 'while', 'If', 'IF'}
OPENERS = {
    'if': 5.1, 'elif': 4.8, 'elseif': 4.8, 'while': 4.5,
    'for': 2.3, 'foreach': 1.8, 'switch': 2.3, 'return': 2.2,
    'assert': 3.2, '&&': 2.3, '||': 2.3, 'and': 0.6, 'or': 0.9,
    'not': 1.5, 'catch': 0.85,
}
NEGATION = {
    'if': 4.2, 'elif': 4.0, 'while': 3.2, 'If': 3.1, 'IF': 3.9,
    'assert': 3.6, 'or': 1.15, 'and': 0.5, 'when': 2.2, 'may': 0.5,
}
TEST_FUNCTIONS = {'isinstance', 'hasattr', 'typeof', 'strcmp'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, age = ('', 50) if first else (carry[1], carry[2] + 1)
    token = prefix.token_strings[-1]
    word, prev = token.strip(), previous.strip()
    value = 0.0
    if word.startswith('(') and ')' not in word:
        rest = word[1:]
        value = OPENERS.get(prev.lower(), 0.08)
        if rest and not rest.startswith(('!', '(', '$', '_')):
            value = 0.4 * value if value > 1.0 else 0.0
        elif prev.lower() in OPENERS:
            value += 0.9 if previous.startswith('\t') else 0.0
            value += 1.5 if rest.startswith('!') else 0.0
            value -= 1.2 if rest.startswith(('$', '_')) else 0.0
            value -= 0.6 if not token.startswith(' ') else 0.0
            value -= 1.4 if '\n' in token else 0.0
        elif previous.isspace():
            value = 0.2 if '\n' in previous else 0.8
        elif not rest and previous.startswith('.'):
            value = 0.6
        if prev in CONDITIONS and prev != prev.lower():
            value *= 0.6
        if first:
            value = 2.91 if token == ' (' else 0.7
    elif word.startswith('!('):
        value = 4.3 if prev == 'assert' else 1.3
        if any(c in word for c in "'\""):
            value = 0.4
    elif word.startswith('['):
        value = (2.9 if prev in CONDITIONS
                 else 0.5 if previous.isspace() else 0.0)
    elif word.lower() == 'not':
        recent = 1.45 if age == 2 else 0.4 if age <= 8 else 0.0
        value = NEGATION.get(prev, recent)
        if first:
            value = 1.0
    elif word == '!':
        value = (1.9 if age <= 6
                 else 0.75 if token.startswith(' ') else 0.08)
    elif word in TEST_FUNCTIONS:
        value = 2.0 if age <= 2 or prev == 'assert' else 0.8
    elif word in {'err', 'len'}:
        value = 1.3 if age == 1 else 0.25
    elif word in {'break', 'continue'}:
        value = -1.0 if token.startswith('\t') else -0.35
    elif word == 'name' and previous.endswith('"'):
        value = 0.33
    elif first and (word == '#' or word.startswith('#!')):
        value = 0.9
    elif first and word in CONDITIONS:
        value = 1.0 if word.islower() else 0.35
    if word in CONDITIONS:
        age = 0
    return (doc, token, min(age, 50)), float(value)

