def step(carry, prefix, upstream):
    return None, float(score(prefix.token_strings[-1]))

programs.sol:
"""Recognize short r-initial consonant fragments and abbreviations.

Two-letter r+consonant tokens are strongest; uppercase and a preceding
consonant increase them. Boundaries, title case, repeated r and digits
weaken them. Three-letter fragments and Arabic/Cyrillic counterparts are
smaller. The Rust suffix .rs is strong even with its leading dot.

Enable-, exhibit- and suspect-words give negative predictions; qualification
and representation words give smaller negative ones. Everything else is
usually zero. These are approximate spelling/word-family rules, not a
complete reconstruction of the component.
"""
import unicodedata

READS = ()
CONSONANTS = frozenset('bcdfghjklmnpqrstvwxz')
QUALIFICATION = ('capable', 'eligible', 'candidate', 'qualifying')
REPRESENTATION = ('diagnos', 'denot', 'depict', 'alleged', 'alleges')
# Consonants in scripts whose r letters are р and ر.
CYRILLIC_CONSONANTS = frozenset('бвгджзклмнпрстфхцчшщ')
ARABIC_CONSONANTS = frozenset('بجحخدذرزسشصضطظعغفقكلمنه')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    core = token.lstrip(' \t\n._/-("')
    lower = core.lower()
    value = 0.0
    if lower == 'its' and previous.strip().lower() == 'exhib':
        value = -1.15
    elif lower.startswith('enabl'):
        value = -0.78 if token.startswith((' ', '.')) and core.islower() else -0.50
    elif lower.startswith('exhib') or lower == 'hibit':
        value = -0.56 if lower.startswith('exhibition') else -1.16
    elif lower.startswith('suspect'):
        value = -1.22 if lower == 'suspected' else -0.67
    elif lower.startswith('suspicion'):
        value = -0.30
    elif lower.startswith(QUALIFICATION):
        value = -0.45
    elif lower.startswith(REPRESENTATION):
        value = -0.29
    elif lower.startswith(('facilitat', 'equipped', 'designated')):
        value = -0.33
    elif lower.startswith(('museum', 'suitable')):
        value = -0.23
    elif token == '.rs':
        value = 1.18
    elif len(core) == 2 and lower[0] == 'r' and lower[1] in CONSONANTS:
        last = unicodedata.normalize('NFD', previous[-1:]).lower()
        last = last[0] if last else ''
        value = 1.10
        if last in CONSONANTS:
            value += 0.25
        elif not last.isalpha():
            value -= 0.15
        if core.isupper():
            value += 0.25
        if last == 'r' and token == core:
            value *= 0.55
        if lower[1] == 'r':
            value *= 0.40
        elif lower[1] in 'hx':
            value *= 0.70
        if core[0].isupper() and core[1].islower():
            value *= 0.50
        if token != core:
            value *= 0.70
        if previous[-1:].isdigit():
            value = 0.72
    elif len(core) == 3 and lower[0] == 'r' and core.isascii() and core.isalpha():
        if lower[1] in CONSONANTS and lower[1] != 'h':
            value = 0.65 if token == core else 0.38
        elif token == core and lower[1] in 'ai':
            value = 0.25
    elif len(core) == 2 and core[0] == 'ر' and core[1] in ARABIC_CONSONANTS:
        value = 0.35
    elif len(core) == 2 and core[0] == 'р' and core[1] in CYRILLIC_CONSONANTS:
        value = 0.50
    elif token in ('р', 'ř', 'ŕ'):
        value = 0.10
    elif token in ('r', '/r', '-r', 'R', '.R'):
        value = 0.14 if token.islower() else 0.10
    return (doc, token), float(value)

"""Approximate a lexical distribution/locality signal and dialogue boundaries.

The biggest responses are to distribution/district stems and fragments.
Smaller word classes describe locations, measurements and personal context;
UI layout names and some Chinese equivalents are recognized too. Tool endings
and message starts have separate spikes; some spatial prepositions are negative.
A following 'of' retains the
signal from 'distribution' or 'district', with state reset per document.
Incomplete UTF-8 token pieces receive their coarse average. Other tokens
receive 0.01. This is a limited surface-word detector, not a claim that every
spatial synonym activates the component or that its wider context is modeled.
"""
READS = ()

# These are surface-word classes, not rules claiming all synonyms behave alike.
WORD_CLASSES = (
    (0.75, "Personal background", """
        family families history historical memory prior situation situations
        background circumstances truth soul society
    """),
    (0.82, "Buildings and neighbourhoods", """
        house houses housing floor floors wall walls street streets
    """),
    (1.4, "Household/residence descriptions", """
        household households residential
    """),
    (0.62, "Spatial or statistical measurements", """
        area areas range ranges layer layers scale scope extent volume curve
        density densities concentration pressure frequency speed speeds slope
        slopes focus focused peak peaks rate rates percentage percentages
        probability probabilities growth partition substantial
    """),
    (0.82, "Extent and coverage", """
        cover covers covered covering coverage spatial spread spreading
        interval intervals throughout
    """),
    (0.62, "Local circumstances", """
        local locally location locations locate close closer closely territorial
        residents foreign ground occupation living scene
    """),
    (0.66, "Time periods", "date dates period periods future"),
    (0.42, "Temporal/spatial distance", "far past moment zone"),
    (0.95, "Extent, remoteness and jurisdiction", "extensive remote jurisdiction"),
    (0.52, "Document/contact attributes", "page pages address addresses profile"),
    (0.72, "Economic context", "market markets forecasting"),
    (0.45, "Prices", "price prices"),
)
CONTEXT_WORDS = {}
for value, concept, words in WORD_CLASSES:
    for word in words.split():
        CONTEXT_WORDS[word] = value

# Chinese distribution/district words, residence, survey and personal status.
# 分布: distribution; 区/區: district; 调查: survey; 生存: survival.
# 住户: household; 户籍: residence registry; 居家/居住: at home/reside.
# 居民: residents; 住宅: housing; 郊: outskirts; 配: allot/distribute.
# 家: home/family; 地: place; 近: near; 状/状态: status; 历史: history.
CHINESE = {
    '分布': 3.9, '分布式': 2.65,
    '区': 1.7, '區': 1.4, '各区': 2.3, '全区': 2.2,
    '调查': 1.9, '生存': 1.9,
    '住户': 2.75, '户籍': 2.5, '居家': 2.0, '居住': 1.7,
    '居民': 1.25, '住宅': 0.9, '郊': 2.0,
    '分配': 1.1, '配送': 1.7, '配': 1.4,
    '家': 0.54, '地': 0.70, '近': 0.64,
    '状': 1.4, '状态': 0.2, '历史': 0.93,
}

BOUNDARIES = {
    '</tool_response>': 1.72,
    '</tool_call>': 1.07,
    '<|im_start|>': 0.65,
    '<|im_end|>': -0.11,
    '<|endoftext|>': -0.08,
    '<think>': 0.69,
    '</think>': 0.49,
    '<tool_call>': -0.12,
}


def lexical_value(token):
    if token in BOUNDARIES:
        return BOUNDARIES[token]
    word = token.strip().lstrip('_./-(')
    lower = word.lower()
    if lower.startswith(('distribution', 'istributions')):
        return 3.75 if lower != 'distributions' else 3.4
    if lower in {'dist', 'distr', 'distrib'}:
        return 3.3 if lower != 'distrib' else 3.05
    if lower.startswith(('district', 'istrict')):
        if lower.endswith('s'):
            return 2.5
        return 3.55 if word == 'District' else 2.85
    if lower.startswith(('distribut', 'redistrib', 'istrib')):
        return 1.95 if lower.startswith('distributor') else 2.7
    if lower.startswith(('distance', 'distant')):
        return 1.0
    if lower.startswith(('distinct', 'distingu')):
        return 0.9
    if lower.startswith('distress'):
        return 1.7
    if lower.startswith('distill'):
        return 2.2
    if lower.startswith(('disturb', 'distract', 'distort')):
        return 0.95
    if token in CHINESE:
        return CHINESE[token]
    # Layout classes organize the spatial placement of UI elements.
    if 'layout' in lower:
        if lower in {'layout', 'layouts'}:
            return 0.72
        return 1.7
    if lower == 'hist':
        return 1.0
    if lower.startswith('survey'):
        return 1.4
    if lower.startswith('investig'):
        return 1.3
    if lower == 'surveillance':
        return 1.0
    if lower.startswith('surviv'):
        return 1.3
    if lower.startswith('statistic'):
        return 1.05 if lower.startswith('statistical') else 0.66
    if lower.startswith('status'):
        return 1.0
    if lower.startswith('url'):
        return 1.0
    if lower == 'where':
        return 1.05
    if lower in {'où', 'donde', 'где'} or token == '哪里':
        return 0.7
    if token == 'どこ':
        return 1.55
    if lower in {'dans', 'sur'}:
        return 0.5
    if lower == 'local' and token.startswith('/'):
        return 1.2
    if lower == 'birthday':
        return 1.0
    if lower == 'schedule':
        return 0.95
    if lower == 'region' or lower == 'regions':
        return 0.3
    if lower == 'located':
        return 0.64
    if lower in CONTEXT_WORDS:
        return CONTEXT_WORDS[lower]
    if lower == 'per':
        return 0.62 if token.startswith(' ') else 0.18
    if lower == 'mm':
        return 0.6
    if token.strip() == '%':
        return 0.39 if token.startswith(' ') else 0.04
    if lower in {'up', 'down', 'over', 'under'}:
        return -0.12
    if lower in {'world', 'across', 'around', 'among', 'beyond', 'toward', 'towards'}:
        return -0.28
    if '\ufffd' in token:
        return 0.2
    if token in {'район', ' район', ' округ'}:
        return 1.7
    return 0.01


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = lexical_value(token)
    word = token.strip().lstrip('_./-(').lower()
    # 'Distribution of' and 'district of' carry the signal onto the complement.
    if word == 'of':
        if previous.startswith('distribution'):
            value = 1.15
        elif previous in {'district', 'districts'}:
            value = 1.2
    if token == '<|im_start|>':
        value = 0.32 if not previous else 0.65
    return (doc, word), float(value)

programs.haiku:
"""Layer-0 MLP feature 2525 (down_proj), read from the current token.

It fires on the 'distribution / district' word family (distribution, District, distributed,
dist, Chinese 分布): strongest, about 3. It fires more weakly (about 1) on other dist- words
(distance, distinct, disturb), and on 'of' right after a dist- word ('District of',
'distribution of'). Medium (about 1.2) on Chinese district/street/residents words and survey
or household words; about 0.8 on place and status words (where, area, located, range, status,
history, ...); about 0.6 to 1.5 on tool and chat tags (</tool_response>, </tool_call>,
<|im_start|>, <think>) and on 'per'. Slightly negative on
'world'. Everything else is about 0. The program reads only the newest token, plus whether the
previous token was a dist- word."""

READS = ()

DIST_STEMS = ("distri", "istrict", "分布", "dist")
DIST_OTHER = ("distan", "distin", "distor", "disturb", "distress", "distract")
DISTRICT_PLACE = {"区", "街", "居民", "疏散"}  # Chinese: district, street, residents, evacuation
SURVEY = {"survey", "survival", "surveillance", "investigate", "investigated", "investigation",
          "调查", "household", "residential", "residents", "families", "family"}
PLACE = {"where", "status", "history", "range", "area", "areas", "located", "local", "/local",
         "house", "market", "period", "rate", "frequency", "speed", "date", "location",
         "interval", "floor", "wall", "walls", "street", "close", "cover", "coverage",
         "territorial", "memory", "prior", "historical", "occupation", "spatial"}
TAGS = {"</tool_response>": 1.5, "</tool_call>": 1.0, "<|im_start|>": 0.6, "<think>": 0.6,
        "per": 0.6}


def is_dist(s):
    """A word of the distribution/district family (not distance, distinct, disturb...)."""
    return any(stem in s for stem in DIST_STEMS) and not s.startswith(DIST_OTHER)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip().lower()
    if s == "of" and carry:
        value = 1.0
    elif is_dist(s):
        value = 3.0
    elif s.startswith(DIST_OTHER):
        value = 1.0
    elif s in DISTRICT_PLACE or s in SURVEY:
        value = 1.2
    elif s in TAGS:
        value = TAGS[s]
    elif s in PLACE:
        value = 0.8
    elif s == "world":
        value = -0.3
    else:
        value = 0.0
    return is_dist(s), value

programs.luna:
"""Predicts a sparse signal at tool handoffs: response ends, call ends, and
the next assistant start within three tokens. Other positions use the
component's overall mean; the rule captures only a small part of its behavior.
"""
READS = ()
TOOL_RESPONSE_END = "</tool_response>"
TOOL_CALL_END = "</tool_call>"
TOOL_ENDS = {TOOL_RESPONSE_END, TOOL_CALL_END}
ASSISTANT_START = "<|im_start|>"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == TOOL_RESPONSE_END:
        return None, 1.7
    if token == TOOL_CALL_END:
        return None, 1.1
    if token == ASSISTANT_START:
        doc = prefix.document_ids[-1]
        for back in range(1, min(4, len(prefix.token_strings))):
            i = len(prefix.token_strings) - 1 - back
            if prefix.document_ids[i] != doc:
                break
            if prefix.token_strings[i] in TOOL_ENDS:
                return None, 0.65
    return None, 0.0175

programs.sol:
"""Recognize decimal-digit pairs, rather than the surrounding topic.

An odd preceding digit from 3 to 9 gives a strong response to middle
following digits (2--7). Increasing the preceding digit weakens it;
following digits at either end reduce it. Zero is a separate exception.
Even predecessors give weaker, differently shaped responses. A decimal
point weakens the response. Similar rules cover fullwidth digits and
adjacent English number words, including tens followed by units.
There is also a small response when a numeral ends, and an initial-digit
response at the start of a document. Everything else is predicted zero.
"""

READS = ()

UNITS = 'zero one two three four five six seven eight nine'.split()
TENS = 'zero ten twenty thirty forty fifty sixty seventy eighty ninety'.split()
INITIAL_DIGITS = (0.16, -0.19, 0.42, 1.58, 0.03,
                  1.30, 0.01, 0.90, -0.20, 0.11)
NUMERAL_BOUNDARY = (0.08, 0.00, 0.06, -0.15, 0.07,
                    -0.13, 0.03, -0.15, 0.06, -0.07)


def numeral(text):
    if len(text) == 1 and '0' <= text <= '9':
        return int(text), 'digit'
    if len(text) == 1 and '０' <= text <= '９':
        return ord(text) - ord('０'), 'wide'
    word = text.strip(' -').lower()
    if word in UNITS:
        return UNITS.index(word), 'unit'
    if word in TENS:
        return TENS.index(word), 'tens'
    return None, None


def digit_pair(previous, current):
    p, c = previous, current
    middle = min(c / 2.0, (9 - c) / 2.0, 1.0)
    if p >= 3 and p % 2:
        if c == 0:
            return -0.6 if p == 7 else (0.0 if p == 9 else -0.3)
        return (2.70 - 0.116 * p + (0.051 - 0.0165 * p) * c
                - (0.771 + 0.010 * p) * max(2 - c, 0)
                - (0.592 - 0.0046 * p) * max(c - 7, 0))
    if p == 2:
        return 0.40 - 0.55 * middle - 0.08 * c / 9 - 0.40 * (c == 0)
    if p == 4:
        return 1.37 - 0.79 * middle - 0.39 * c / 9 - 0.41 * (c == 0)
    if p in (6, 8):
        return 1.038 - 0.077 * p - 0.15 * middle + (0.0685 * p - 1.128) * c / 9
    return -0.01 if p == 0 else -0.05


def numeral_ending(previous, text):
    # A following word or blank marks a numeral boundary. Punctuation
    # gives a smaller reaction; letters joined directly are left out.
    word = text.strip()
    if not word or (text[0].isspace() and word.isalpha()):
        return NUMERAL_BOUNDARY[previous]
    if not any(ch.isalnum() for ch in word):
        return 0.55 * NUMERAL_BOUNDARY[previous]
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    old_text, older_text = ('', '') if fresh else carry[1:]
    text = prefix.token_strings[-1]
    current, current_kind = numeral(text)
    previous, previous_kind = numeral(old_text)
    value = 0.0
    if fresh and current_kind == 'digit':
        value = INITIAL_DIGITS[current]
    elif previous_kind == 'digit' and current is None:
        value = numeral_ending(previous, text)
    strength = 0.0
    if current_kind == previous_kind == 'digit':
        strength = 1.0
    elif current_kind == previous_kind == 'wide':
        strength = 0.68
    elif previous_kind == 'tens' and current_kind == 'unit':
        strength = 1.10 if text.startswith('-') else 0.51
    elif previous_kind == current_kind == 'unit':
        strength = 0.47
    elif old_text == '.' and current_kind == 'digit':
        previous, previous_kind = numeral(older_text)
        if previous_kind == 'digit':
            strength = 0.36
    if strength:
        value = strength * digit_pair(previous, current)
    return (doc, text, old_text), float(value)

