programs.sol:
"""Approximate this component with token-local m-ending spelling rules.

Isolated m/M and short consonant+m fragments receive the largest values.
The gain depends on length, case, leading whitespace, and the preceding
letter; vowel digraphs and common grammatical words receive little weight.
An ending -s retains part of the signal. Cyrillic em, Arabic mim, and Greek
mu have weaker rules. A bare m/M is boosted after an adjacent consonant,
never across a document boundary. This omits lexical and richer-context
variation rather than encoding an arbitrary token lookup.
"""
import unicodedata

READS = ()
FUNCTION_WORDS = frozenset(('am', 'him', 'them', 'from', 'whom'))
VOWELS = frozenset('aeiouı')
VOWEL_DIGRAPHS = frozenset(('ee', 'oo', 'ea', 'ai'))


def m_ending(text):
    s = text.strip()
    if not s:
        return 0.0
    space = text[:1].isspace()
    lower = s.lower()
    if lower in ("'m", '’m'):
        return 0.1
    # These are whole grammatical words, rather than m-ending fragments.
    if lower in FUNCTION_WORDS:
        if lower != 'am' or (s == 'am' and space):
            return 0.02
    if lower in ('μ', 'µ'):
        return 0.2 if space else 0.4
    if lower.endswith('м'):
        if len(s) == 1:
            return 0.95 if space else 1.15
        if len(s) == 2 and lower[-2] not in 'аеёиоуыэюя':
            return 1.7
        if lower == 'ем':
            return 0.2
        return 0.6 if len(s) <= 4 else 0.35
    if lower.endswith('م'):
        return 0.75 if len(s) <= 4 else 0.2
    if not lower.endswith('m'):
        return 0.0

    # Ignore punctuation before a fragment, but preserve its word boundary.
    fragment = s.lstrip('._/\\-+*([<,:;=$&')
    n = len(fragment)
    if n == 1:
        if space:
            return 1.2 if fragment.isupper() else 0.92
        return 1.4

    before = unicodedata.normalize('NFD', fragment[-2].lower())[0]
    if n >= 4 and fragment[-3:-1].lower() in VOWEL_DIGRAPHS:
        return 0.05
    upper = fragment.isupper()
    if before == 'm':
        return 0.8 if n == 2 else 0.4
    if before == 'r':
        if n <= 3:
            return 0.65 if space and n == 3 else 1.35
        return 0.25 if n <= 5 else 0.1
    if before == 'l':
        return 2.4 if n <= 3 else 1.0 if n <= 5 else 0.25
    if before == 'y':
        if n == 2:
            return 2.6 if upper else 2.1
        if fragment.lower().endswith('sym'):
            return 0.65
        return 2.0 if n <= 5 else 0.8
    if before == 's':
        if n <= 3:
            return 2.1 if fragment.lower() == 'ism' else 3.1
        return 1.5 if n <= 5 else 0.3
    if before.isalpha() and before not in VOWELS:
        if n == 2:
            base = 2.3 if not space or upper else 2.0
            if before in 'dgt':
                base += 0.8
            return base
        if n == 3:
            return 2.2 if not space or upper else 1.3
        return 0.6 if n <= 5 else 0.3
    if n == 2:
        return 0.65 if upper else 0.25 if space else 0.48
    if n <= 5:
        return 0.3
    return 0.08


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    s = text.strip()
    if s.lower().endswith('ms'):
        value = (0.28 if s.lower() == 'ms'
                 else 0.55 * m_ending(text[:-1]))
    else:
        value = m_ending(text)
    if s in ('m', 'M') and text == s:
        previous = ''
        if (prefix.position > 0 and
                prefix.document_ids[-2] == prefix.document_ids[-1]):
            previous = prefix.token_strings[-2][-1:]
        consonant = (previous.isalpha() and
                     unicodedata.normalize('NFD', previous.lower())[0]
                     not in VOWELS and previous.lower() != 'm')
        if s == 'M':
            value = 1.8 if consonant else 1.3
        else:
            value = 1.7 if consonant else 1.1
    return None, float(value)

programs.haiku:
"""Layer-0 MLP component 2528 (down_proj): a detector for the letter "m".

The component writes into the residual stream when the current token is an m:
  * the bare letter (m, M, Cyrillic м, and Arabic/Thai م, ม): about 1.3;
  * a short fragment whose last letter is m (or Cyrillic м) after a consonant, e.g.
    GM, SM, DM, PM, sm, dm, cm, km, ism, ym: about 2, up to 3 for capitalised
    abbreviations;
  * an m after a vowel (am, im, om, um): weak, about 0.3;
  * an m after r or h (arm, firm, harm): weak, about 0.6.
Common English words ending in m (from, form, them, team, term) are about 0, and
tokens of 4 or more letters get a smaller value. Everything else is 0.

The program has no state: it reads only the newest token, decoded alone.
"""

READS = ()

ALONE = {"m", "M", "м", "М", "م", "ม"}
VOWELS = set("aeiouаеёиоуыэюя")
COMMON_WORDS = {"from", "form", "them", "him", "term", "team", "sum", "norm",
                "warm", "farm", "harm", "firm", "arm", "some", "room", "time"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    lower = token.lower()
    value = 0.0
    if token in ALONE:
        value = 1.3
    elif len(lower) >= 2 and lower[-1] in "mм" and lower[-2].isalpha():
        if lower not in COMMON_WORDS:
            before = lower[-2]
