BOUNDARIES = '._(/\\=:@$\'"[]-'


def lexical_value(token):
    plain = token.strip()
    word = plain.strip(BOUNDARIES).lower()
    if word == 'request':
        if plain.isupper() or token.startswith(('\t', '(', '=')):
            return -4.2
        return -6.3 if token == 'request' else -5.3
    if word in {'requests', 'requested', 'requesting'}:
        return -4.3 if token.startswith(' ') else -3.9
    if word == 'req':
        return -2.3
    if 'request' in word:
        if 'mapping' in word or 'dispatcher' in word:
            return -0.7
        return -3.9 if word == 'getrequest' else -2.1

    # Request/application, request (Japanese), and request (Korean/Russian).
    if plain in {'请求', '申请', '申請'}:
        return -4.8
    if plain == '請求':
        return -3.6
    if plain == '요청':
        return -3.1
    if 'запрос' in word:
        return -2.0
    # Chinese 'please', Japanese/Chinese seeking, needing, and polite asking.
    if plain in {'請', '请', '，请'}:
        return -2.2 if plain == '請' else -1.75
    if plain in {'求', '需求', '的需求', '申し', '祈祷'}:
        return -1.25
    if plain in {'ください', '下さい', '申し込み'}:
        return -0.9
    if word in {'applicant', 'applicants'}:
        return -1.7
    if word in {'please', 'bitte', 'demand', 'demands', 'demanded', 'demanding'}:
        return -0.9
    if word in {'query', 'queries', 'petition', 'petitions', 'prayer', 'prayers'}:
        return -0.75
    if word in {'download', 'downloaded', 'downloading', 'downloads', 'uploaded'}:
        return -0.85
    if word in {'fetch', 'fetched', 'prefetch', 'upload', 'uploads'}:
        return -0.5
    if word in {'purchase', 'purchased', 'purchasing', 'purchases'}:
        return -0.55
    if word in {'response', 'responses'}:
        return -0.35 if token.startswith(' ') and plain.islower() else -0.75
    # Purchasing, obtaining, downloading, and demanding in Chinese.
    if plain in {'購', '购', '购买', '选购', '采购', '获取', '下载', '要求'}:
        return -0.6
    if word == 'browser' or plain in {'GET', 'POST'}:
        return -0.45
