    if token in {'ing', 'ed', 's'} and root == 'request':
        value = -3.2
    elif token == 'ed' and root == 'download':
        value = -0.64
    if root == 'request':
        if token == ' of':
            value = -1.5
        elif token in {' to', ' for', ' the', ' a', ' an'}:
            value = -0.4
    return (doc, token), float(value)

