programs.sol:
"""Predict activation from the onset of two-letter uppercase tokens.

These may be standalone abbreviations or the start of longer acronyms.
A preceding capital suppresses the pulse. Opening delimiters strengthen it;
digits, within-word placement, and attached punctuation weaken it. Small
Roman numerals and US/UK/EU/UN also get weaker predictions. Document starts
and other tokens get zero. Individual abbreviations' amplitudes are not
modeled: this captures their shared capitalization and boundary pattern.
"""
import re

READS = ()
SMALL_ROMAN_NUMERALS = {'II', 'IV', 'VI', 'IX', 'XI', 'XV', 'XX'}
INTERNATIONAL_INITIALS = {'US', 'UK', 'EU', 'UN'}
CAPITAL_PAIR = re.compile(r'([\W_]*)([A-Z]{2})\Z')


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    match = CAPITAL_PAIR.fullmatch(token)
    value = 0.0
    if match and not first:
        leading, letters = match.groups()
        if previous[-1:].isupper():
            value = 0.04 if leading else -0.02
        elif letters == 'II':
            value = 0.0
        elif letters in SMALL_ROMAN_NUMERALS:
            value = 0.23
        elif letters in INTERNATIONAL_INITIALS:
            value = 0.38
        elif leading.strip():
            value = 0.33
        elif previous[-1:].isdigit():
            value = 0.40
        elif not leading and previous[-1:].islower():
            value = 0.43
        elif previous.rstrip().endswith(('(', '[')):
            value = 0.78
        else:
            value = 0.64
    return (document, token), value

"""Approximate a prose-quotation pulse, rather than parse quotation pairs.

Space-prefixed quotation marks receive large negative values after words,
especially speech/name introducers. Punctuation weakens the pulse. Familiar
code syntax in the previous 64 tokens suppresses straight-quote responses.
Smaller rules cover other quote styles, closing marks, and Markdown
emphasis. Almost all ordinary text gets zero. State resets at each document boundary.
"""
import math

READS = ()
INTRODUCERS = set('called named entitled titled termed known means saying said '
                   'says say stated states wrote writes word phrase that'.split())
CODE_WORDS = set('return echo print printf import export throw raise typeof '
                 'instanceof yield await console comment'.split())
CORNER_QUOTES = {'「': -1.7, '『': -1.2, '《': -0.45}


def code_strength(text):
    """Evidence of source code or serialized data, accumulated over 64 tokens."""
    word = text.strip()
    score = 0.15 * any(c in word for c in '{}=;')
    score += 0.04 * any(c in word for c in '[]')
    score += 0.08 * any(s in word for s in ('\\n', '\\t', '\\"', "\\'"))
    score += 0.24 * (len(text) > 1 and text.isspace() and '\n' not in text)
    # NAME placeholders are redacted names, not programming identifiers.
    score += 0.10 * ('_' in word and not word.startswith('NAME'))
    score += 0.12 * any(a.islower() and b.isupper()
                       for a, b in zip(word, word[1:]))
    score += 0.22 * word.endswith(('\",', "',"))
    score += 0.40 * word.endswith(('\":', "':"))
    return score + 0.13 * (word.lower() in CODE_WORDS)


def opening(previous, code, single=False):
    word = previous.strip()
    ratio = 0.6 if single else 1.0
    if not word:
        if '\n' in previous:
            return -2.6
        return 0.35 if len(previous) > 1 else 0.18
    if word.lower() in CODE_WORDS:
        return -0.15
    if word.endswith(':') and any(c in word for c in '\"\'”’'):
        return 0.17
    if word.endswith(',') and any(c in word for c in '\"\'”’'):
        return 0.18 - (0.35 if single else 1.9) * math.exp(-1.25 * code)
    if any(c in word for c in '=+{}[]\\<>') or word in {'(', ')', ';', '/'}:
        return 0.15 - math.exp(-1.4 * code)
    if word.lower() in INTRODUCERS:
        strong = word.lower() in {'that', 'entitled', 'called', 'titled'}
        base = -5.6 if strong else -4.7
        return base * ratio * math.exp(-0.2 * code)
    base = (-2.9 if word.endswith(':') else -4.0 if word.endswith(',') else
            -3.1 if word.endswith(('.', '!', '?')) else
            -2.2 if word.endswith(('\"', "'", '”', '’')) else
            -4.3 if previous[:1].isspace() and word[-1].isalpha() else -2.8)
    if single and word.endswith((':', ',')):
        ratio = 0.45
    return base * ratio * math.exp(-(1.4 if single else 1.0) * code)


def token_value(text, previous, code):
    mark = text.strip()
    spaced = text[:1].isspace()
    if text.endswith(('\n', '\r')) and mark in {'\"', "'", '”', '’'}:
        return 0.02
    if spaced and mark in {'(\"', '(“', "('"}:
        return -2.75 if mark == '(“' else 0.6 * opening(previous, code, mark == "('")
    if spaced and mark in {"''", '``'}:
        return opening(previous, code, True)
    if mark in {'\"', "'"}:
        if spaced:
            return opening(previous, code, mark == "'")
        if mark == "'":
            return -0.15
        if previous.strip().endswith(('.', ':')) or '\n' in previous:
            return -1.5 * math.exp(-0.75 * code)
        size = 0.85 if previous[:1].isspace() else 0.65
        return 0.15 - size * math.exp(-0.75 * code)
    if mark in {'“', '‘', '„'}:
        if not spaced:
            return -1.0 if mark == '‘' else -1.3
        word = previous.strip().lower()
        base = (-5.0 if word in INTRODUCERS else -3.2 if word.endswith(':') else
                -3.55 if word.endswith(('.', '!', '?')) else -4.3)
        return base * {'“': 1.0, '‘': 0.72, '„': 0.66}[mark]
    if mark in {'”', '’'}:
        if previous and '\u3400' <= previous[-1] <= '\u9fff':
            return 0.03  # Closing mark after a CJK ideograph.
        return -2.0 if spaced else -0.4
    if mark in {'«', '»'}:
        return (-2.3 if mark == '«' else -1.1) if spaced else -0.5
    if mark in CORNER_QUOTES:
        return CORNER_QUOTES[mark]
    if mark in {'`', '``'}:
        return 0.2 - 0.5 * math.exp(-code) if spaced else 0.19 if mark == '`' else 0.0
    if mark == '**':
        return -0.66 if spaced else -0.14
    if mark == '*' and spaced:
        after_word = previous.strip().isalpha() and previous[:1].isspace()
        return opening(previous, code) * 0.12 if after_word else 0.08
    if spaced and mark.startswith(('\"[', '\"`', '“[')):
        return opening(previous, code)
    if mark[:1] in {'\"', '“', '‘', '„'} and len(mark) > 1:
        if mark[1].isalpha():
            return (-0.65 if len(mark) == 2 else -1.05) * math.exp(-0.75 * code)
        if mark[1] in ',.':
            return -0.2 * math.exp(-0.5 * code)
    return -0.75 if '“' in mark and not any(c.isalpha() for c in mark) else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, history, code = '', (), 0.0
    else:
        _, previous, history, code = carry
    text = prefix.token_strings[-1]
    value = token_value(text, previous, code)
    strength = code_strength(text)
    code += strength - (history[0] if len(history) == 64 else 0.0)
    history = (history + (strength,))[-64:]
    return (doc, text, history, max(0.0, code)), float(value)

