    token = prefix.token_strings[-1]
    stripped = token.lstrip()

    if token != stripped and stripped[:1] in DOUBLE_OPEN:
        return None, -1.44 if stripped[0] == '"' else -1.76
    if token.startswith(('“', '「', '«')):
        return None, -0.4
    if stripped == "'" and token != stripped:
        return None, -0.6
    if stripped == '`' and token != stripped:
        return None, -0.12
    if stripped == "'":
        return None, -0.14
    if token.startswith('**'):
        return None, -0.28
    return None, 0.0

