USE = {'use': -4.50, 'used': -3.74, 'using': -2.95, 'uses': -3.18}
NEED = {'need': -1.04, 'needs': -0.90, 'needed': -0.79, 'needing': -0.78}
RELATED = {
    'useful': -1.40, 'useless': -1.27, 'usefulness': -1.58,
    'usable': -1.40, 'usage': -0.98, 'utility': -0.62, 'utilities': -0.40,
    'unused': -1.40, 'reuse': -2.07, 'reused': -1.80,
    'misuse': -2.40, 'abuse': -1.23, 'abused': -1.44,
    'employ': -1.25, 'employed': -1.30, 'employing': -1.43, 'employs': -1.17,
}


def use_response(token, previous, word, prior):
    value = USE[word]
    joined = token[:1].isalpha() and previous[-1:].isalpha()
    if joined:
        if token.istitle():  # A new word within a camelCase identifier.
            return {'use': -3.7, 'used': -3.4, 'uses': -3.75,
                    'using': -2.8}[word]
        value = {'use': -2.6, 'used': -1.5, 'using': -1.5, 'uses': -0.9}[word]
        # Non-USE words: diffuse, confuse, refuse, infuse, peruse, cause, pause.
        if prior.endswith(('diff', 'conf', 'ref', 'inf', 'per', 'ca', 'pa')):
            value = -0.55
        elif prior.endswith('oten'):  # hypotenuse
            value = -0.92
        elif prior.endswith('exc'):  # excuse
            value = -1.1
        return value
