        if token[:1] in '._-/(':
            value = -5.7
        elif not token[:1].isspace():
            value = -4.5 if token.istitle() or token.isupper() else -4.9
        elif prior in {'can', 'could', 'should', 'must'}:
            value -= 0.55
        elif prior in {'in', 'no', 'not', 'its'}:
            value += 0.55
    elif word == 'used':
        if prior == 'be':
            value -= 0.47
        elif prior in {'was', 'were', 'are', 'we', 'who'}:
            value += 0.30
        elif prior == 'not':
            value += 0.70
    elif word == 'using':
        if prior in {'am', "'m", '’m', 'consider', 'suggests', 'tried'}:
            value -= 0.55
        elif prior in {'when', 'for', 'while'}:
            value -= 0.35
        elif previous.endswith(';\n'):
            value = -2.3
