    if stem in USE:
        value = use_response(token, previous, stem, prior)
    elif word in NEED:
        value = NEED[word]
        if word == 'need':
            if prior in {'the', 'a', 'no'}:
                value += 0.25
            elif prior in {"'ll", '’ll'}:
                value -= 0.50
            elif prior == 'will':
                value -= 0.25
    elif word in RELATED:
        value = RELATED[word]
    elif word == 'of' and prior in {'use', 'usage'}:
        value = -1.02
    elif word == '.util':
        value = -2.05
    elif word.strip("._-/'’") == 'util':
        value = -1.2 if len(word) > 4 or token[:1].isspace() else -0.70
    elif word.startswith(('utiliz', 'utilis')):
        value = -0.98 if word.endswith(('ization', 'isation')) else -1.7
    elif token.strip().startswith('use') and token.strip()[3:4].isupper():
        value = -2.65  # camelCase hooks: useState, useEffect, ...
    # Words and roots meaning 'use' in other languages.
    elif word.startswith('использ') or word in {'ольз', 'ользов'}:
        value = -2.4 if word.startswith('использ') else -1.9
    elif word in {'uso', 'usar', 'usando'} and token[:1].isspace():
        value = -2.1
    elif word in {'사용', '이용', 'ใช', 'استخدام'}:
        value = -2.2 if word != 'ใช' else -2.9
    elif '使用' in word:
        value = -0.5 if word.endswith('者') else -1.82
    elif '利用' in word:
        value = -1.45
    elif word == '用':
        value = -2.45
        if previous.endswith('调'):
            value = -0.78  # 调用: call/invoke
        elif previous.endswith(('採', '活', '雇')):
            value = -1.45
        elif previous.endswith('试'):
            value = -1.8
