        value = -2.7
    elif word in {'可用', '有用', '用途', '用了', '用自己的', '可以用', '用人'}:
        value = -1.9
    elif word in {'用于', '用品', '采用', '运用', '用来', '应用', '备用'}:
        value = -0.93
    elif word in {'使う', '使い', '使える', 'を使う'}:
        value = -1.25
    return (doc, token), float(value)

