    "utilize", "utilise", "utilized", "utilizing", "utilizes", "utilization", "utilisation",
    "utilisé", "utiliser", "utilizar", "utiliza", "utilis", "util", "employ", "employed",
    "employs", "employing",
}
FOREIGN_PREFIXES = ("使用", "用", "использ", "ольз", "usar", "usando", "uso", "ใช", "사용")
