ARROWS = {"=>", "==>", "⇒", "⟹"}
SUGGEST = {"suggest", "suggests", "suggested", "suggesting", "suggestion", "suggestions", "suggestive"}
IMPLY = {"imply", "implies", "implied", "implying", "implication", "implications", "impl", "Impl", "plies", "plied"}
SIGNAL = {"indicate", "indicates", "indicated", "indicating", "indication", "indications",
          "recommend", "recommends", "recommended", "recommendations", "propose", "proposed",
          "reveal", "reveals", "revealed", "revealing", "hint", "clue", "clues", "means", "meaning", "meanings", "leading"}
OPERATORS = {"=", ":=", "->", "-->", "→", "::", ")=", "}=", "===", "&&", ".g", ".e"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    if tok in ARROWS:
        return None, 4.2
    if tok in SUGGEST:
        return None, 3.6
    if tok in IMPLY:
        return None, 1.8
    if tok in SIGNAL:
        return None, 0.7
    if tok in OPERATORS:
        return None, 0.55
    return None, 0.0

