def response(token):
    word = token.strip().lstrip('._/-')
    lower = word.lower()
    if lower == 'che':
        if word.islower():
            return -2.4
        return -3.35 if word.isupper() else -3.75
    if lower == 'ache':
        return -2.25
    if lower in ('cache', 'caches', 'cached'):
        if lower.endswith('d'):
            return -1.4
        return -2.0 if lower.endswith('s') else -2.4
    if lower.startswith('cheat'):
        return -1.9
    if lower in ('queue', 'queues', 'helper', 'helpers'):
        if lower == 'helpers' and token.startswith(('/', '.')):
            return -0.5
        return -1.1
    if lower == 'que':
        return -0.4 if word.islower() else -1.0
    if token in ('he', 'HE'):
        return -0.72 if token == 'he' else -1.25
    if lower == 'sche':
        return -1.5
    if lower == 'iche':
        return -0.98
    if lower in ('ches', 'aches'):
        return -0.9
    if lower == 'ached':
        return -1.3
    if lower.startswith(('cheese', 'cheek', 'chef')):
        return -0.9
    if lower.startswith(('chem', 'schema')):
        return -0.4
    if lower.startswith('check'):
        return 0.0
    if 'che' in lower and len(lower) <= 5:
        return -0.25
    return 0.0


def step(carry, prefix, upstream):
    return None, response(prefix.token_strings[-1])

