"""Predicts layers.0.mlp.down_proj:2539, a component that reads "the" and "by".

It is active on the word "by" (any case) and on the word "the" (any case).
- "by" is about 1.0, except after math verbs ("divided by", "multiplied by"), where it is about 0.3.
- "the" depends on the word just before it:
  * after a preposition or conjunction ("by the", "under the", "between the",
    "and the", ", the"): high, about 1.0;
  * after "of", "in", "on", "at", "is", "that" and similar: medium, about 0.5;
  * at a sentence or line start, after a verb or pronoun, or after "do" and "make":
    low, about 0.1 (and about -0.7 after "do" or "make").
- The level is raised in dense technical prose and lowered in casual narrative. That is
  estimated from the average length of the last 30 letter-only words: longer words
  mean more technical prose.
- Every other token predicts 0.

Only the current token and the previous word, plus a running average of word lengths
kept in the carry, are used.
"""

READS = ()

HIGH_BEFORE_THE = {
    "by", "under", "during", "within", "between", "through", "across",
    "into", "along", "upon", "via", "among", "towards", "or", "and", "to", ",", ";",
}
MID_BEFORE_THE = {
    "of", "in", "on", "at", "from", "with", "about", "for", "as", "over",
    "around", "after", "before", "while", "since", "because", "against",
    "than", "where", "when", "which", "that", "is", "was", "are", "be", "(", ")",
}
LOW_BEFORE_THE = {
    "", ".", '"', ":", "all", "if", "so", "but", "maybe", "perhaps", "make", "use",
    "have", "get", "do", "see", "keep", "add", "take", "like", "how", "what", "i",
    "you", "me", "we", "they", "he", "she", "it",
}
MATH_VERBS = {"divided", "multiplied", "divisible", "step", "times", "multiply", "divide"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    new_doc = len(prefix.token_ids) < 2 or bool(prefix.document_ids[-2] != prefix.document_ids[-1])
    words = [] if carry is None or new_doc else list(carry)
    if word.isalpha():
        words = (words + [len(word)])[-30:]
    next_carry = tuple(words)
    before = "" if new_doc else prefix.token_strings[-2].strip()
    if word == "by":
        return next_carry, 0.3 if before.lower() in MATH_VERBS else 1.0
    if word != "the":
        return next_carry, 0.0
    if new_doc:
        return next_carry, 1.0
    if before in HIGH_BEFORE_THE:
        level = 1.0
    elif before.lower() in ("do", "make"):
        return next_carry, -0.7
    elif before.lower() in LOW_BEFORE_THE:
        level = 0.1
    elif before in MID_BEFORE_THE or before.lower() in MID_BEFORE_THE:
        level = 0.6
    else:
        level = 0.5
    # Average length of the recent words: longer words suggest technical prose.
    register = sum(words) / len(words) - 4.0 if words else 0.0
    return next_carry, level + 0.2 * register

