        if spaced:
            return -1.68 if previous[-1:].isdigit() else -2.08
        if raw == word:
            last = previous[-1:].lower()
            if last.isalpha():
                return -2.52 if last in 'aeiou' else -3.18
            if last.isdigit():
                return -2.00
            return -2.25 if word == 'x' else -2.12
        return -2.16 if word == 'x' else -2.35

    if word and set(lower) == {'x'}:
        return -1.90
    if len(word) == 2 and lower.endswith('x'):
        if lower[0] == 'e':
            return -0.06
        if lower[0] in 'aiu':
            if word[0].isupper() and word[1].islower():
                return -1.93
            if lower[0] == 'a' and not spaced:
                return -0.57
            return -1.26 if spaced else -0.95
        return -3.03 if spaced else -3.37

