        return -0.95
    if lower in ('index', 'indices', 'indexes', 'indexing'):
        return -0.63
    if lower.startswith('cross') or lower == 'across':
        return -0.87
    if lower == 'width':
        return -1.12

    if lower.endswith('x') and len(lower) < 5:
        if lower in ('fix', 'six', 'mix'):
            return 0.03
        if lower.endswith('ox'):
            return -2.19
        if lower[-2] in 'aeiu':
            return -0.20
        return -1.61
    if lower.endswith('x'):
        return -0.05
    if lower.startswith('x') and len(lower) <= 3:
        return -0.33

    if word in ('×', 'χ', 'Χ', 'ξ', 'Ξ'):
        return -0.81
    if word in ('х', 'Х'):
