    'Fig': (3.6, 5.8, 5.2, 5.1),
    'FIG': (3.3, 4.7, 3.6, 4.5),
    'Figure': (4.1, 6.8, 5.8, 4.7),
    'Figures': (2.8, 6.2, 4.8, 4.8),
    'Table': (2.4, 6.1, 5.6, 4.0),
    'Tables': (1.3, 4.9, 3.7, 3.0),
    'TABLE': (2.2, 5.7, 3.5, 3.5),
    'Eq': (1.5, 2.9, 2.7, 2.4),
    'Section': (1.1, 3.2, 1.7, 1.7),
}
WEAKER_LABELS = {
    'figure': 0.8, 'figures': 0.4, 'fig': 0.7, 'table': 0.1,
    'equation': 0.82, 'equations': 0.54, 'Equation': 1.8,
    'section': 0.55, 'sections': 0.35, 'subsection': 2.1,
    'Sect': 2.6, 'Sec': 0.65, 'Ref': 0.5, 'Abb': 1.35,
    'Appendix': 3.2, 'appendix': 2.2, 'Algorithm': 1.5,
    'Lemma': 1.8, 'Proposition': 1.5, 'theorem': 0.5,
    'Supplementary': 1.7, 'Article': 0.35,
    'Note': 0.5, 'http': 0.5, 'https': 0.65, '§': 0.8,
}
