    'Fig': 3.6, 'Figs': 5.1, 'figs': 1.4,
    'Figure': 3.5, 'Figures': 4.0, 'FIGURE': 3.4, 'FIGURES': 2.4,
    'Appendix': 2.8, 'APPENDIX': 2.8, 'Appendices': 2.7,
    'Equation': 1.45, 'equation': 1.45, 'Equations': 0.55,
    'Eqs': 3.0, 'eqs': 1.0, 'theorem': 0.85, 'Theorem': 0.85,
    'label': 0.85, 'Footnote': 1.5, 'footnote': 0.8,
