        if phase.startswith('plural') or label == 'Figs':
            factor *= 0.45
        if phase == 'space':
            factor *= 0.3
        return power * factor, (label, power, 'space')
    if word.isdigit() and phase == 'space':
        return power * (0.04 if label in {'Fig', 'FIG'} else 0.085), None
    if word.startswith('(') and label in {'Eq', 'Equation', 'equation'}:
