        value = plain
        if joined:
            value = 0.1
        elif cue in {'in', 'see'}:
            value = cited
        elif paren:
            value = spaced_paren if spaced else bare_paren
        elif heading or '#' in previous:
            value *= 1.0 if word.isupper() else 0.75
        elif word in {'Fig', 'Figure', 'Table'} and cue in {'of', 'from', 'by', 'to'}:
