            elif paren or previous.endswith('['):
                value = 3.1
            elif previous.endswith('#'):
                value = 1.8
        if word in {'figure', 'fig', 'table'} and previous.endswith('{'):
            value = {'figure': 4.1, 'fig': 3.0, 'table': 3.2}[word]
        if word in {'figure', 'fig', 'table', 'section'} and cue in {'in', 'see'}:
            value += 1.5 if word != 'figure' else 2.7
        if word == 'section' and cue in {'this', 'next', 'under', 'by', 'of'}:
            value = 1.15
        if word in {'Sec', 'Ref'} and cue in {'in', 'see', 'from'}:
            value += 1.1
