        word, value = whole, COMPLETIONS[whole]
    if value is not None:
        reference = (word, value, 'label')
    else:
        value, reference = continue_reference(token, reference)
    if word == 'see' and paren:
        value = 0.97
    elif word in {'align', 'aligned'} and previous.endswith('{'):
        value = 1.1 if word == 'align' else 0.8
    elif token == ' able':
        value = 0.25 if cue == 'be' else 0.7
    elif token == 'ис':
        value = 3.7 if previous == ' р' else 1.05
    elif word in {'图', '圖'}:
        value = 2.4 if paren or cue in {'下', '如下', '上', '如'} else 0.4
        if cue in {'见', '見'}:
            value = 5.0
