programs.luna:
"""Mark figure/table labels and a handful of reference-writing cues.

Figure and table terms get the strongest predictions. The program gives
smaller values to equation/section/article/note/formula/theorem words, §,
http(s), and able suffixes. It briefly tracks punctuation, spaces, and digits
after Fig/Table.
"""

READS: tuple[str, ...] = ()

FIGURE_WORDS = {"fig", "figs", "figure", "figures"}
TABLE_WORDS = {"table", "tables"}
REFERENCE_WORDS = {
    "equation": 0.9, "equations": 0.8,
    "section": 0.8, "sections": 0.7,
    "article": 0.7, "articles": 0.6,
    "note": 0.6, "notes": 0.5,
    "formula": 0.3, "formulas": 0.3,
    "theorem": 0.5, "theorems": 0.4,
    "able": 0.7, "http": 0.6, "https": 0.6,
}


def _word(token):
    return token.lstrip().strip()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = _word(token)
    folded = word.casefold()
    doc = prefix.document_ids[-1]

    if folded in FIGURE_WORDS:
        if word.isupper():
            value = 3.8
        elif word[:1].isupper():
            value = 5.1
        else:
            value = 1.5
        return (doc, "figure", 1), float(value)

    if folded in TABLE_WORDS:
        value = 4.4 if word[:1].isupper() else 1.2
        return (doc, "table", 1), float(value)

    if word == "§":
        return None, 0.85
    if folded in REFERENCE_WORDS:
        value = REFERENCE_WORDS[folded]
        if word[:1].isupper() and folded == "section":
            value += 0.8
        return None, float(value)
    if folded.endswith(("able", "iable")):
        return None, 0.55

    if carry is None or carry[0] != doc:
        return None, 0.0
    _, label, age = carry
    if label not in {"figure", "table"}:
        return None, 0.0

    # The next few tokens in a reference are often a period, blank, and number.
    if age == 1:
        if word == ".":
            return (doc, label, 2), 1.7 if label == "figure" else 0.2
        if label == "figure" and folded == "s":
            return (doc, label, 2), 2.8
        if not word:
            return (doc, label, 2), 1.8
        if word[:1].isdigit():
            return None, 0.3
    elif age == 2:
        if not word:
            return (doc, label, 3), 1.7
        if word[:1].isdigit():
            return None, 0.3
        if word == ".":
            return (doc, label, 3), 0.5
    elif age == 3 and word[:1].isdigit():
        return None, 0.3

    return None, 0.0

