READS = ()


def lexical(token):
    word = token.lstrip(" ._-(").lower()
    if word in {"pair", "pairs"}:
        value = 6.0 if word == "pair" else 5.7
        if token.startswith("("):
            value *= 0.8
        if token.strip().isupper():
            value *= 0.4
        return value
