        return 2.5
    if word == "pairwise":
        return 1.75
    if word == "copy":
        return 1.5
    if word == "copies":
        return 1.25
    if word == "copying":
        return 0.8
    if word in {"couple", "couples"}:
        return 1.0
    if word == "twins":
        return 0.8
    if word == "twin":
        return 0.4
    if word in {"triple", "triples"}:
