"""Layer-0 MLP down-projection component 2542: a "pair" detector.

It fires on the word "pair" and on words built on it or meaning a pair, couple or
duplicate, and a little on words that rhyme with "pair" ("air", "fair", "chair").
Values are in the component's own activation units (about 6 on "pair"):

  pair, pairs (any case; with a leading space, underscore or bracket)     6.0
  paired, pairing, cặp (Vietnamese "pair")                                 2.5
  couple(s), triple(t)(s), tuple(s), twin(s), duo, quad(...)              1.2
  copy, copies, copied                                                    1.3
  coordinate(s), combination(s), candidate(s), quadratic                  0.9
  air, airs, chair, fair with a leading space                             1.0
  air, airs, chair, fair without one (a fragment, as in "P|air")          2.5
  对, 双, 對, 这对, пар (pair in Chinese and Russian)                      1.0

The word "of" right after a pair word takes 40% of that word's value ("a pair of":
about 2.4 after "pair", 0.6 after "copy"). Everything else is 0. The program keeps no
state beyond the previous token of the same document.
"""

READS = ()

PAIR = {"pair", "pairs"}
PAIR_RELATED = {"paired", "pairing", "cặp"}
TWO_OR_THREE = {
    "couple", "couples", "triple", "triplet", "triplets", "triples", "tuple",
    "tuples", "twin", "twins", "duo", "quad", "quadr",
}
COPY = {"copy", "copies", "copied"}
MATH = {
    "coordinate", "coordinates", "combination", "combinations", "candidate",
    "candidates", "quadratic",
}
AIR = {"air", "airs", "chair", "chairs", "fair"}
PAIR_OTHER_LANGUAGES = {"对", "双", "對", "这对", "пар"}
OF_SHARE = 0.4


def word(token):
    """The token's letters: without spaces, underscores, brackets or dots; lower case."""
    return token.strip(" _(<.-\n\t").lower()


def strength(token):
    """How strongly one token, decoded alone, drives the component."""
    w = word(token)
    if w in PAIR:
        return 6.0
    if w in PAIR_RELATED:
        return 2.5
    if w in TWO_OR_THREE:
        return 1.2
    if w in COPY:
        return 1.3
    if w in MATH:
        return 0.9
    if w in AIR:
        return 1.0 if token.startswith(" ") else 2.5
    if w in PAIR_OTHER_LANGUAGES:
        return 1.0
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = strength(token)
    same_document = len(prefix.token_strings) > 1 and (
        prefix.document_ids[-2] == prefix.document_ids[-1]
    )
    if token.strip() == "of" and same_document:
        value = OF_SHARE * strength(prefix.token_strings[-2])
    return None, float(value)

