"""Detect agent/source spellings: chiefly 'by', and more weakly 'from'.

Past-participle + 'by' is stronger than arithmetic or 'step by'.
Capitalization matters, and the spelling signal also leaks into identifiers
and byte-related tokens. Chinese/Japanese/Indonesian agent markers get
moderate values. Unrecognized tokens are zero; no full syntax is inferred.
"""
import re

READS = ()
ARITHMETIC = {'divide', 'divided', 'dividing', 'division', 'multiply',
              'multiplied', 'multiplying', 'divisible', 'sides', 'denominator'}
RELATIONS = {'given', 'obtained', 'determined', 'defined', 'characterized',
             'described', 'represented', 'related', 'known'}
COMMUNICATION = {'asked', 'written', 'reported', 'directed', 'posted'}
CAUSATION = {'caused', 'inspired', 'affected', 'influenced'}
IRREGULAR = {'made', 'shown', 'seen', 'held', 'taken', 'built', 'driven'}
SEPARATION = {'away', 'apart', 'different', 'differ', 'derived', 'extracted',
              'taken', 'removed', 'excluded', 'isolated', 'free', 'far'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    match = re.search(r'(\w+|[^\w\s]+)\s*$', tail)
    previous = match[1].lower() if match else ''
    participle = previous.endswith('ed') or previous in IRREGULAR
    raw = prefix.token_strings[-1]
    token = raw.strip()
    value = 0.0
    if token == 'by':
        value = 2.6
        if raw.startswith(' '):
            if previous == 'step':
                value = 0.4
            elif previous in ARITHMETIC:
                value = 1.0
            elif previous in RELATIONS or previous in COMMUNICATION:
                value = 2.4
            elif previous in CAUSATION:
                value = 2.6
            elif previous.isdigit():
                value = 2.2
            elif participle:
                value = 3.3
    elif token == 'By':
        value = 4.5 if participle else 3.8
    elif token == 'BY':
        value = 2.4
    elif token in {'/by', '_by', '-by'}:
        value = 2.0 if token == '-by' else 3.8
    elif re.fullmatch(r'By[A-Z][a-z]*', token):
        value = 1.7
    elif token.endswith('By'):
        value = 0.9
    elif 'byte' in token.lower():
        value = 0.5
    elif token.lower() in {'thereby', 'whereby', 'hereby'}:
        value = 0.3
    elif token.lower().lstrip('._/(#-') == 'from':
        if token == 'from' and raw.startswith(' '):
            value = 0.08 if previous in SEPARATION else 0.43
            if previous == '}':
                value = 0.72
        else:
            value = 0.56 if token == 'FROM' else 0.75
    elif token.endswith('被'):
        value = 1.28
    elif token == 'によって':
        value = 1.23
    elif token == 'oleh':
        value = 1.03
    return (doc, (tail + raw)[-80:]), value

