"""Layer-0 MLP down-projection component 2543: the agent "by" of a passive construction.

Reads the token "by" in any capitalisation ("managed by", "adopted by", "permitted by",
"By the end ..."), and responds most strongly when "by" follows a past participle.
It is weaker on "by" in the arithmetic/procedural sense ("divided by", "step by step"),
and weaker still on "from" ("derived from", "away from"). Everything else is 0.
"""

READS = ()

BY_TOKENS = {" by", "by", " By", "By", " BY", "BY", "-by", "/by"}
FROM_TOKENS = {" from", "from", " From", "From", " FROM", "FROM"}
NON_AGENT_BY_PREVIOUS = {"step", "divided", "divisible"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in BY_TOKENS:
        previous = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
        if previous in NON_AGENT_BY_PREVIOUS:
            return carry, 0.6
        return carry, 2.9
    if token in FROM_TOKENS:
        return carry, 0.5
    return carry, 0.0

