    (-0.28, 'helpful effective practical comfortable convenient intuitive '
            'advantageous timely'),                 # utility and ease
    (-0.21, 'skilled talented equipped confident confidence trust trusted '
            'enthusiastic interested'),             # competence/engagement
    (0.11, 'necessary specific unique relevant significant responsible '
           'available impossible'),                # necessity/specificity
    (-0.18, 'lesson lessons worksheet worksheets mathematics maths skills'),
    (-0.30, 'ways fashion manner'),
    (-0.20, 'days daily evening'),
    (-0.11, 'steps directions guidance'),       # procedural guidance
    (-0.09, 'single multiple either'),          # count alternatives
    (-0.04, 'any each both'),                   # distributive quantifiers
    (-0.065, 'thus therefore'),                 # consequence
    (0.055, 'because due'),                     # cause
    (0.08, 'often sometimes'),                  # frequency
    (0.15, 'access freedom affordable flexible'),
    (0.07, 'null undefined none'),              # missing-value literals
