VOWEL_ENDINGS = {
    'ī': 1.0, 'ē': 0.75, 'ā': 0.36, 'ō': 0.38, 'ū': 0.36,
    'ี': 1.3, 'ู': 0.35, 'ึ': 0.18, 'ื': -0.08,
    'ੀ': 1.9, 'ீ': 1.9, 'ీ': 1.9, 'ী': 1.9,
    'ी': 2.15, 'ू': 0.60, 'ा': 0.25, 'ो': 0.35, 'े': 0.15,
    'ی': 0.10, 'ي': 0.10,
