            elif c == 'น':
                value = 1.7
            elif c in 'บชล':
                value = 1.65
            elif c in 'พปคหฟ':
                value = 0.65
        elif previous.endswith('ี่'):
            value = (0.65 if c == 'ด' else 0.30) / n
        elif vowel == 'ู' and c == 'ด':
            value = 0.95 / n
        elif vowel == 'ึ' and c == 'ด':
            value = 0.49 / n
        elif vowel == 'ी' and c == 'न':
            value = 1.3 / n
        elif vowel in 'ੀீీী':
