"""Approximate a negative response to a digit-like date after 'the'.

It marks the gap after 'the' and the first digit following that gap, using
only the prefix seen so far; other component responses are not modeled.
"""

READS = ()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    documents = prefix.document_ids
    current = tokens[-1].strip()
    same_as_previous = (
        len(tokens) >= 2 and documents[-1] == documents[-2]
    )
    if same_as_previous and not current:
        if tokens[-2].strip().lower() == "the":
            return None, -0.8
    same_three = (
        len(tokens) >= 3
        and documents[-1] == documents[-2] == documents[-3]
    )
    if current.isdigit() and same_three:
        if not tokens[-2].strip() and tokens[-3].strip().lower() == "the":
            return None, -0.8
    return None, 0.0

