"""A local signal for joining clauses, especially 'and it' and 'and also'.

Subject pronouns receive a strong negative value after a coordinator and a
positive value after a question word or thinking verb. Demonstratives,
negation, and additive adverbs have related responses. A conjunction two
tokens back has a weaker, lingering effect. Modal verbs also change the
responses of 'also' and 'not'. Other tokens predict zero.
This is a grammatical approximation, not a vocabulary-wide lookup table.
"""
import re

READS = ()

SUBJECTS = {
    'it': 1.63, 'they': 1.40, 'you': 1.16,
    'he': 1.06, 'she': 1.00, 'we': 0.79, 'I': 0.71,
    'this': 1.07, 'these': 0.69, 'there': 0.79,
}
LINKS = {
    'and': -1.00, 'or': -0.65, 'but': -0.19,
    'then': -0.37, 'so': -0.23, 'now': -0.25, 'yet': -0.33,
    'while': -0.26, 'since': -0.11,
    'what': 0.32, 'why': 0.47, 'if': 0.08,
    'when': 0.05, 'whether': 0.13, 'where': -0.09,
    'which': -0.07, 'as': 0.06,
}
ADDITIONS = {
    'also': -2.24, 'not': -0.86, 'that': -0.36,
    'then': -0.27, 'every': -0.70, 'each': -0.50,
    'another': -0.57, 'all': -0.31, 'now': -0.36,
    'only': -0.34, 'never': -0.60, 'still': -0.43,
    'even': -0.23, 'later': -0.39,
}
DETERMINERS = {
    'the': -0.16, 'his': -0.25, 'its': -0.21,
    'their': -0.19, 'her': -0.23, 'your': -0.18,
    'other': -0.13, 'those': -0.20,
}
THINKING = {'think', 'thought', 'believe', 'know', 'find', 'found', 'feel'}
NEGATIVE_PREPOSITIONS = {'to', 'with', 'by', 'on', 'than'}
POSITIVE_PREPOSITIONS = {'of', 'about', 'like'}
ALSO_CONTEXT = {
    'may': 0.47, 'might': 1.00,
    'can': -0.23, 'could': -0.41, 'would': -0.30,
    'is': 0.25, 'was': 0.17, 'see': 0.60,
    'but': -0.20, 'we': -0.35, 'they': -0.27,
    'i': -0.17, 'he': -0.17, 'she': -0.17, ',': -0.25,
}


def linking_strength(previous):
    word = previous.lower()
    if word in THINKING:
        return 0.23
    if word in NEGATIVE_PREPOSITIONS:
        return -0.14
    if word in POSITIVE_PREPOSITIONS:
        return 0.08
    if word in {'give', 'gives', 'help'}:
        return -0.20
    if word in {'is', 'are'}:
        return 0.16
    if word in {',', ';'}:
        return -0.05
    strength = LINKS.get(word, 0.0)
    # Sentence-initial coordinators produce a slightly weaker response.
    return strength * (0.8 if previous[:1].isupper() else 1.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before = ('', '')
    if carry is not None and carry[0] == doc:
        previous, before = carry[1:]
    raw = prefix.token_strings[-1]
    word = raw.strip()
    prev = previous.lower()
    value = 0.0
    if raw.startswith(' '):
        if word in SUBJECTS:
            strength = linking_strength(previous)
            if before.lower() == 'and' and prev != 'and':
                strength -= 0.17
            value = SUBJECTS[word] * strength
        elif prev == 'and':
            value = ADDITIONS.get(word, DETERMINERS.get(word, 0.0))
            if previous[:1].isupper():
                value *= 0.8
        elif word == 'also':
            value = ALSO_CONTEXT.get(prev, 0.0)
            if before.lower() == 'and':
                value -= 0.60
        elif word == 'not':
            value = {'or': -0.67, 'may': 0.63, 'might': 0.40,
                     'but': -0.09, ',': -0.12}.get(prev, 0.0)
            if before.lower() == 'and':
                value -= 0.23
        elif prev == 'or':
            value = 0.65 * DETERMINERS.get(word, 0.0)
    # Recognize a joining word even when its token includes a leading dash.
    match = re.search(r'[A-Za-z]+$', word)
    remembered = match.group() if match else word
    return (doc, remembered, previous), float(value)

