programs.sol:
"""Negative activation for token-final v/V, strongest in short fragments.

Vowel endings, whitespace, longer fragments and recent Czech/Slovak accented text
weaken the response. Attached uppercase letters strengthen it. The Cyrillic
v-sound has a smaller response. Television and viral word forms are additional
weak triggers, as are environment word stems. Document boundaries reset state.
Most other tokens predict approximately zero; width variants are normalized.
"""
import re
import unicodedata

READS = ()
TAIL = re.compile('[A-Za-z]+$')
CZECH_SLOVAK_ACCENTS = frozenset('ěščřžýáíéůúďťňľĺó')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, recent = ('', '') if carry is None or carry[0] != doc else carry[1:]
    text = unicodedata.normalize('NFKC', prefix.token_strings[-1])
    word = text.strip().lower()
    spaced = bool(text and text[0].isspace())
    tail = TAIL.search(text)
    value = -0.002
    if tail and word.endswith('v'):
        letters = tail[0]
        if len(letters) == 1:
            value = -2.2 + 0.35 * spaced
            if len(word) > 1:
                value += 0.35
            elif not spaced and previous[-1:].isascii() and previous[-1:].isalpha():
                value -= 0.8
                if text[-1] == 'V' and previous[-1].isupper():
                    value -= 0.9
        else:
            vowel = letters[-2].lower()
            value = -1.8 if vowel in 'io' else -2.35 if vowel in 'ae' else -3.15
            value += 0.5 * min(len(letters) - 2, 2) + 0.2 * spaced
            if text[-1] == 'V':
                value += 0.2 if vowel == 'i' else -0.6
        if text[-1] == 'V' and not spaced and len(letters) <= 2:
            attached = TAIL.search(previous)
            if attached and any(c.isupper() for c in attached[0]):
                value -= 0.3 * min(2, len(attached[0]))
        value += 0.25 * min(3, sum(c in CZECH_SLOVAK_ACCENTS for c in recent.lower()))
    elif word.endswith('в'):
        value = (-0.06 if spaced else -0.28) if word == 'в' else -0.65
        if word.endswith('ов'):
            value += 0.25
        elif word.endswith('ств'):
            value += 0.45
    elif word == 'television':
        value = -1.7
    elif word.startswith(('virus', 'viral')) or word == '病毒':
        value = -0.8
    elif word == 'covid':
        value = -1.3
    elif word.startswith('environ'):
        value = -0.4
    return (doc, text, (recent + text)[-96:]), float(value)

"""A lexical art-and-science cue, not a passage-topic classifier.

Art, artists, and Chinese art characters give the strongest responses. Science,
creative work, culture, technology and expertise give progressively weaker ones.
The gains approximate training activations. Token case and boundaries matter.
One-token memory handles 'art of', split word endings and a few compounds;
'computer science', 'martial arts' and 'social media' have reduced responses.
All other tokens predict zero, and memory resets across documents.
"""
READS = ()

# Familiar semantic families, with their approximate response strengths.
TECHNOLOGY = set('''technology technological engineering craft crafts
    craftsmanship artificial techn scientifically'''.split())
DESIGN = set('''design designs designer designers architecture architect
    architects tech technologies engineer engineers talented'''.split())
CULTURE = set('''culture cultural music musician musicians poetry poet poets
    nature medium sculpture designing academia genre industry industrial
    academic academics research researcher researchers technical creativity
    architectural genius sculpt'''.split())
EXPERTISE = set('''knowledge expertise expert experts skill skilled talent
    profession professions professionals intellectual literary fiction doctor
    doctors medicine biology press theatre theater drama patent discipline
    methodology'''.split())
METHODS = set('''process works studies designed director professional'''.split())


def lexical_value(token):
    text = token.strip()
    word = text.lower()
    spaced = token.startswith(' ')
    if word == 'art':
        if spaced:
            return 1.75 if text.isupper() else (3.05 if text == 'Art' else 3.8)
        return 2.65 if text == 'Art' else 0.7
    if word == 'artistic':
        return 3.7
    if word == 'arts':
        return 0.4 if text == 'arts' and not spaced else 3.2
    if word in {'artist', 'artists'}:
        return 2.3 if text == 'Artist' else 2.85
    if word in {'artwork', 'artworks', 'artisan', 'artisans'}:
        return 2.3
    if word in {'-art', '_art', '/art', '.art'}:
        return 2.7
    if text == 'Ar':
        return 0.68
    if word == 'science':
        return 0.9 if token == 'science' else (1.8 if text == 'Science' else 2.0)
    if word == 'scientific':
        return 1.55
    if word in {'sciences', 'scientist', 'scientists', 'scient', 'humanities'}:
        return 1.25
    if word in TECHNOLOGY or word in {'artifact', 'artifacts', 'ünst'}:
        return 1.05
    if word == 'creative':
        return 0.7 if text[:1].isupper() else 1.15
    for family, strength in (
        (DESIGN, 0.85), (CULTURE, 0.7), (EXPERTISE, 0.53), (METHODS, 0.2),
    ):
        if word in family:
            return strength
    if word in {'literature', 'skills', 'outside', 'technique', 'techniques',
                'ology', 'ological', 'ologie'}:
        return 0.35
    if word in {'media', 'inside', 'ologist', 'ologists'}:
        return 0.65
    if word == 'style':
        return 0.25 if spaced else 0.0
    if word == 'work':
        return 0.13
    # Corresponding art/science stems outside English.
    if word.startswith('искус') or word == 'nghệ':
        return 3.2
    if word == '예술':
        return 2.35
    if word in {'kunst', '예', 'issenschaft'} or word.startswith(
        ('наук', 'науч', 'технолог')
    ):
        return 1.45
    if word == 'arte':
        return 1.5 if spaced else 0.2
    if word == 'tecn' or word.startswith('теат'):
        return 0.7
    # Art characters are especially strong; compounds are weaker.
    if text in {'艺', '藝'}:
        return 7.7 if text == '艺' else 6.8
    if text in {'艺术', '的艺术'}:
        return 4.8
    if text in {'藝術', '文艺', '文藝', '工艺', '工藝'}:
        return 4.1
    if any(c in text for c in '艺藝'):
        return 2.2 if text in {'演艺', '演藝'} else 3.3
    if text in {'芸', '美术', '美術'}:
        return 2.8
    if text in {'科学', '科學', '科技', '科学技术'}:
        return 1.95
    if text.startswith(('科研', '科技')) or text in {'科幻', '学术', '學術'}:
        return 1.5
    if ('技术' in text or '技術' in text
            or text in {'科', '術', '技', '术', '技法', '学科'}):
        return 1.25
    if text in {'文学', '文學', '工业', '工業', '考古', '创作', '創作'}:
        return 1.15
    if text in {'文化', '工程', '工', '诗', '詩', '设计师', '設計師', '医师', '醫師'}:
        return 0.9
    if text in {
        '设计', '設計', '行业', '行業', '产业', '產業', '美', '業', '业', '音乐', '音樂',
    }:
        return 0.75
    if text in {'文', '学', '學', '专业', '專業', '专家', '專家', '技能'}:
        return 0.63
    if text in {'乐', '樂', '楽', '歌', '研究', '医', '醫', '医学', '醫學', '画', '畫'}:
        return 0.48
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    word = token.strip().lower()
    value = lexical_value(token)
    if carry is not None and carry[0] == doc:
        previous_token = carry[1]
        previous = previous_token.strip().lower()
        if token == ' of':
            if previous_token in {' art', ' Art', 'Art'}:
                value = 2.1 if previous_token == ' Art' else 2.35
            elif previous in {'artist', 'arts', 'science'}:
                value = 1.3 if previous == 'artist' else 0.9
        elif (word, previous) in {('science', 'computer'), ('arts', 'martial')}:
            value = 1.1 if word == 'science' else 2.1
        elif word == 'media' and previous == 'social':
            value = -0.04
        elif token.startswith(' ') and word in {
            'art', 'arts', 'artist', 'artists', 'science',
        } and previous in {'the', 'an'}:
            value += 0.35
        elif previous in {'art', 'scient', 'techn'} and token in {
            'ist', 'ists', 'istic', 'istry', 'isans', 'ific', 'ological', 'ology',
        }:
            value = 1.35
    return (doc, token), float(value)

