    'whereas': -1.9, 'except': -0.43, 'unless': -0.28,
    'vs': -0.35, 'versus': -0.35, '!==': -0.2, '+++': -0.6,
    '不同于': -4.2, '不像': -2.2, '相比': -1.3, '相比于': -1.8,
}
