FROM = {
    'different': -5.4, 'differ': -4.5, 'differs': -4.8,
    'distinct': -4.4, 'distinguished': -4.0, 'distinguish': -4.6,
    'distinguishes': -4.3, 'distinguishing': -3.3,
    'distinguishable': -4.1, 'separate': -3.1, 'separated': -2.0,
    'apart': -1.8, 'away': -0.55, 'far': -1.0, 'aside': -0.9,
}
TO = {
    'contrast': -4.4, 'contrary': -2.9, 'opposite': -2.6,
    'different': -2.7, 'similar': -1.9, 'compared': -1.8,
    'opposed': -1.9, 'alternative': -1.7, 'comparison': -1.3,
    'comparable': -1.2, 'prefer': -1.4, 'preferred': -1.2,
    'identical': -0.9, 'relative': -0.38,
}
WITH = {
    'contrast': -2.8, 'contrasts': -3.2, 'compared': -1.1,
    'compare': -1.0, 'comparison': -1.0, 'disagree': -0.77,
    'consistent': -0.46, 'inconsistent': -0.8,
    'compatible': -0.7, 'incompatible': -1.1, 'agreement': -0.24,
