def nearby(words, cues, limit=4):
    for distance, word in enumerate(reversed(words[-limit:])):
        if word.lower() in cues:
            return cues[word.lower()] * 0.78 ** distance
    return 0.0

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    words = WORDS.findall(text.replace('\\n', ' ').replace('\\t', ' '))
    prev = words[-1].lower() if words else ''
