            value = -10.0 if token == token.strip() else -9.5
    elif prev == 'unlike' and word in {'the', 'this', 'that', 'a', 'an'}:
        value = -0.6 if word in {'a', 'an'} else -1.2
    elif word == 'contrast':
        value = -1.6 if prev == 'in' else -0.7
    elif word == 'than':
        value = -0.8
        if prev == 'rather':
            value = -2.3 if capital else -1.63
        elif prev == 'other':
            value = -1.05
        elif prev in {'more', 'less', 'greater'}:
            value = -0.1 if prev == 'more' else -0.22
        elif prev in {'better', 'worse', 'faster', 'slower', 'easier', 'harder'}:
            value = -1.25
        elif prev in {'larger', 'bigger'}:
            value = -0.56
