        if recent & {"opposite", "instead", "regardless", "independent"}:
            value = -1.3
    elif word == "with":
        if recent & {"compare", "compared", "contrast", "contrasts", "disagree",
                     "consistent", "inconsistent", "different", "alongside"}:
            value = -1.2
    elif word in {"versus", "vs"}:
        value = -1.0

    return (doc, text), value

programs.sol:
"""Negative responses to message delimiters and programming-name spellings.

Chat, thought and tool delimiters have the largest responses. Their magnitude
increases with document position, approximated by an inverse-square-root early
correction. A closing chat marker immediately after a tool delimiter is weaker.

The smaller lexical response recognizes Error/Exception suffixes, known code
libraries and functions, and camel-case or dot/underscore-prefixed names.
Long compound names are stronger; generic variable suffixes and a few common
mixed-case proper names are exempted. Other token spellings predict zero.
This is a lexical approximation, not code execution or a token-ID lookup.
"""
import re

READS = ()
# Each marker: late-document response, early-position correction,
# and response when it is the very first token.
BOUNDARIES = {
    '<|im_end|>': (-5.855, 1.587, -3.305),
    '<think>': (-5.334, 0.909, -3.107),
    '</think>': (-6.028, 1.170, -3.608),
    '<tool_call>': (-7.023, 1.517, -4.938),
    '</tool_call>': (-4.027, 0.855, -2.259),
    '<tool_response>': (-5.870, 1.529, -3.291),
    '</tool_response>': (-5.430, 1.373, -2.695),
}
JAVA_FRAMEWORKS = {
    'springframework', 'junit', 'hibernate', 'servlet', 'vaadin',
    'awt', 'swing', 'appcompat', 'recyclerview', 'lombok',
}
PYTHON_BUILTINS = {'isinstance', 'hasattr', 'getattr', 'setattr', 'issubclass'}
C_IO = {'printf', 'sprintf', 'fprintf', 'scanf', 'sscanf', 'fscanf',
        'fopen', 'fclose', 'fwrite', 'fread', 'strcpy', 'strcat'}


def identifier_value(token):
    name = token.strip().lstrip('.@_([/-')
    if not name or not name.isascii() or not name.isalpha():
        return 0.0
    length = len(name)
    if name.endswith(('Error', 'Exception')):
        if name == 'Error':
            return -0.15
        if name == 'Exception':
            return -1.1
        return -3.1 - 0.18 * max(0, length - 8)
    if name in JAVA_FRAMEWORKS and token.startswith(('.', '@')):
        return -3.0 - 0.10 * max(0, length - 8)
    if name in ('androidx', 'javax', 'pyplot', 'tqdm'):
        return -2.5
    if name in PYTHON_BUILTINS:
        return -2.1
    if name.lower() in C_IO:
        return -1.1
    if token.startswith('_') and name in ('modules', 'replace'):
        return -1.05
    if name in ('JavaScript', 'TypeScript', 'YouTube', 'PlayStation'):
        return 0.0
    if re.match(r'Mc[A-Z]', name):
        return 0.0
    compound = bool(re.search(r'[a-z][A-Z]|[A-Z]{2}[a-z]', name))
    if compound:
        if name.endswith(('Name', 'Value', 'Type', 'Count', 'Index', 'Size')):
            return -0.2
        if name[0].isupper():
            value = -0.40 * max(0, length - 4)
        else:
            value = -0.15 * max(0, length - 5) - 0.30 * max(0, length - 10)
        if token.startswith('.') and name[0].isupper():
            value -= 0.7
        return value
    if token.startswith('.'):
        return -0.07 * max(0, length - 2)
    if token.startswith('_'):
        return -0.05 * max(0, length - 4)
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    position = 0 if first else carry[2] + 1
    early = 1.0 / (position + 1) ** 0.5
    if token == '<|im_start|>':
        value = (-2.711 if first or previous == '<|endoftext|>'
                 else -4.684 + 1.449 * early)
    elif (token == '<|im_end|>'
          and previous in ('</tool_call>', '</tool_response>')):
        value = -5.604 + 2.392 * early
    elif token in BOUNDARIES:
        late, correction, initial = BOUNDARIES[token]
        value = initial if first else late + correction * early
    else:
        value = identifier_value(token)
    return (doc, token, position), float(value)

programs.luna:
"""Approximate two recurring patterns: chat-control markers and code names."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()

    if word.startswith(("<|", "<tool_", "</tool_", "<think", "</think")):
        return None, -5.0

    code_name = False
    if token.startswith((".", "->", "::")) and len(word) > 1:
        code_name = any(char.isalpha() for char in word[1:])
    if word.startswith(("/", "-")) and len(word) > 3:
        code_name = True

    letters = [char for char in word if char.isalpha()]
    if len(letters) >= 4 and any(c.isupper() for c in letters):
        if any(c.islower() for c in letters):
            code_name = True

    return None, -0.45 if code_name else 0.0

programs.sol:
"""Conversation markup evokes strong positive signals, especially closing tags.

A message end following a tool call is weaker than the end of ordinary text.
Message starts are stronger when they begin the model's visible document.
All non-markup tokens are approximated by zero.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    start = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if start else prefix.token_strings[-2]
    if token == '<|im_start|>':
        value = 1.657 if start else 1.477
    elif token == '<|im_end|>':
        if previous == '</tool_call>':
            value = 1.793
        elif previous == '</tool_response>':
            value = 2.058
        elif previous in ('。', '？', '！'):
            value = 2.35
        else:
            value = 2.22
    elif token == '</tool_response>':
        value = 2.374
    elif token == '</think>':
        value = 2.292
    elif token == '<think>':
        value = 1.057
    elif token == '<tool_call>':
        value = 1.019 if start else (0.217 if previous == '\n' else 0.30)
    elif token == '</tool_call>':
        value = 0.082
    elif token == '<tool_response>':
        value = 0.109
    else:
        value = 0.0
    return None, value

