programs.sol:
"""A lexical ratio/comparison detector, not a sentence-level comparison parser.

比 ('than/compare') and ratio have the largest responses. Related comparison,
proportion and degree words respond less strongly. Spelling fragments also
fire in names and unrelated words: the initial UTF-8 bytes of 比 are shared
with 毎 and 母. 'Than' is weaker in less/fewer comparisons and nearly absent
in rather/other than. 'Of' briefly echoes a quantitative relationship noun.
"""
READS = ()

# Known tokenizer spellings of the first bytes of 比 (UTF-8 E6 AF 94).
BI_PREFIX = 29975                 # E6 AF
AF_BYTE = 107                    # AF
E6_LEADS = {162, 6567}            # E6, or space followed by E6

ENGLISH_GROUPS = (
    (4.1, {'ratio', 'ratios'}),
    (2.35, {'atio'}),             # A ratio-like subword ending.
    (1.1, {'compare', 'compares', 'compared', 'comparing', 'compar',
           'comparison', 'comparisons', 'comparable', 'comparative'}),
    (1.6, {'comparatively', 'proportion', 'proportions', 'disproportion'}),
    (1.0, {'contrast', 'contrasts', 'proportional', 'disproportionate'}),
    (0.7, {'percentage', 'percentages', 'relatively', 'fairly'}),
    (0.4, {'fraction', 'fractions', 'versus', 'among'}),
)
PERIOD_COMPARISONS = {'同比', '环比'}
RATIO_TERMS = {'比例', '的比例', '占比', '比重', '比分'}
COMPARING_TERMS = {'相比', '对比', '對比', '比率'}
OF_ECHO = {
    'ratio': 1.7, 'ratios': 1.1, 'proportion': 1.0, 'proportions': 0.7,
    'comparison': 0.6, 'fraction': 0.5, 'percentage': 0.3,
}


def spelling_value(text):
    word = text.strip(' \n\r\t_.').lower()
    for value, forms in ENGLISH_GROUPS:
        if word in forms:
            return value
    bare = text.strip()
    if bare == '比':
        return 10.0
    if bare in PERIOD_COMPARISONS:
        return 5.9
    if bare in RATIO_TERMS:
        return 5.0
    if bare in COMPARING_TERMS:
        return 4.1
    if bare in {'要比', '比我'}:
        return 8.0
    if bare in {'比较', '较', '較'}:
        return 2.6
    if bare in {'比較', '比べ', '不如'}:
        return 2.0
    if bare == '比起' or bare.startswith(('同比', '环比')):
        return 3.0
    if bare.startswith('比如'):
        return 0.6
    if '比' in bare:
        return 1.6
    if '较' in bare or '較' in bare:
        return 0.9
    if bare == '비':
        return 4.55 if text[:1].isspace() else 3.2
    if bare == '보다':
        return 2.1
    if bare in {'より', 'よりも', 'の方が', 'ほうが', '비교'}:
        return 1.3
    if bare in {'ビ', 'び', 'べ'}:
        return 1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    previous, previous_id = carry[1:] if same_doc else ('', -1)
    token_id = prefix.token_ids[-1]
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    value = spelling_value(text)
    if token_id == BI_PREFIX:
        value = 3.2
    elif token_id == AF_BYTE and previous_id in E6_LEADS:
        value = 2.5
    elif '\ufffd' in text and same_doc:
        ending = prefix.text_prefixes[-1][-1:]
        if ending == '比':
            value = 12.3
        elif ending in {'ビ', 'ピ', 'び'}:
            value = 2.0
    if word == 'than':
        if previous in {'rather', 'other'}:
            value = 0.03
        elif previous in {'less', 'fewer'}:
            value = 0.25
        elif previous in {'greater', 'better', 'smaller', 'lower', 'worse'}:
            value = 0.65
        else:
            value = 0.82
    elif word == 'ios' and previous == 'rat':
        value, word = 4.6, 'ratios'
    elif word == 'atio' and previous.endswith('r'):
        value, word = 3.5, 'ratio'
    elif word == 'of':
        value = OF_ECHO.get(previous, 0.0)
    return (doc, word, token_id), value

programs.luna:
"""Predict the sparse comparison-marker response from the current token alone."""

READS: tuple[str, ...] = ()

COMPARISON_WORDS = {
    "than", "compare", "compares", "compared", "comparing",
    "comparison", "comparisons", "comparative", "comparatively",
    "contrast", "contrasts", "contrasted", "contrasting",
    "relative", "relatively", "proportion", "proportions",
    "ratio", "ratios", "versus", "vs",
}

ASIAN_MARKERS = (
    "比较", "比較", "相比", "对比", "對比", "よりも", "より", "比べ",
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold().strip()
    word = "".join(ch for ch in token if ch.isalnum())

    if "比分" in token:
        return None, 3.0
    if token == "比":
        return None, 4.5
    if "比如" in token:
        return None, 0.65
    if any(marker in token for marker in ASIAN_MARKERS) or "比" in token:
        return None, 1.25

    if word in COMPARISON_WORDS:
        if word in {
            "comparison", "comparisons", "comparative", "comparatively",
            "proportion", "proportions", "contrast", "contrasted",
        }:
            return None, 1.25
        return None, 0.9
    return None, 0.0

programs.sol:
"""Predict a lexical descent/lowering signal, dominated by Chinese 降.

Chinese compounds containing 降 have a smaller response than the character
alone. English descent/lowering words and translated equivalents have
weaker responses; delivery words also have a secondary negative response.
One-token memory recognizes split compounds and prepositions after a decrease.
The document-opening word Title gets its own negative baseline. Other lexical
responses, including many small background activations, are not modeled.
"""

READS = ()

LOWERING = {'lowering', 'lowered', 'lowers'}
DESCENT = {'descent', 'descendant', 'descending'}
DECREASE = {'decrease', 'decreased', 'decreases', 'decreasing'}
DROPS = {'drop', 'dropped', 'drops', 'dropping'}
FALLS = {'fall', 'falls', 'fallen', 'falling'}
SPLIT_DESCENT = {'下': -2.0, '息': -1.1, '水量': -0.88}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1].strip()
    word = text.strip('._(').lower()
    value = 0.0

    if text == '降':
        value = -3.85 if previous == '以' else -4.8
    elif text in {'降到', '降至', '降落'}:
        value = -2.7
    elif text in {'降临', '降价'}:
        value = -1.5
    elif '降' in text:
        value = -4.5 / (len(text) + 0.3)
    elif text == '升':
        value = -0.67
    elif text == '落':
        value = -0.75 if previous == '堕' else -0.18
    elif text == '退市':
        value = -0.8
    elif text == '↓':
        value = -0.3
    elif word in LOWERING:
        value = -0.6
    elif word == 'desc':
        value = -0.65 if text.startswith('.') else -0.48
    elif word in DESCENT:
        value = -0.42
    elif word in {'descend', 'descended', 'descendants'}:
        value = -0.19
    elif word == 'lower':
        value = -0.4 if text.startswith('.') else -0.17
    elif word in {'lowercase', 'tolowercase'}:
        value = -0.43
    elif word in DECREASE:
        value = -0.2
    elif word in DROPS:
        value = -0.24
    elif word in FALLS:
        value = -0.7 if previous.lower() == 'land' else -0.16
    elif word in {'downgrade', 'precipitation'}:
        value = -0.43
    elif word == 'surrender':
        value = -0.25
    elif word == 'deliver':
        value = -0.41
    elif word in {'delivered', 'delivering', 'delivers', 'deliveries'}:
        value = -0.22
    elif word == 'delivery':
        value = -0.14
    elif word == 'giảm':
        value = -0.55
    elif word == 'hạ':
        value = -1.0

    if previous == '降' and text in SPLIT_DESCENT:
        value = SPLIT_DESCENT[text]
    prev_word = previous.strip('._(').lower()
    if prev_word in LOWERING | DECREASE | DROPS | FALLS | DESCENT:
        if word == 'of':
            value = -0.45 if prev_word in LOWERING | DECREASE else -0.25
        elif word == 'in':
            value = -0.28
        elif word == 'the':
            value = -0.18
    if text == 'Title' and not previous:
        value = -0.56
    return (doc, text), value

